/* CorpIT AI Governance. Structured records and explicit project mappings;
   catalogue membership, policy coverage, approval and usage stay separate. */
(function(){'use strict';
const $=id=>document.getElementById(id),API='/api/zscaler/governance';
let categories=['Dedicated AI Platform','AI Development Platform','AI Agent / Automation Platform','Application with Embedded AI Features','AI Security / Operations Tool'];
const titles={'use-cases':['Use-Case Inventory','One record per AI use case from the InfoSec / Legal workbook, each linked to a catalog application.'],'purpose-intake':['Business purpose intake','Collect scoped owner and purpose answers, review evidence and keep suggestions separate from confirmation.'],dashboard:['Governance Dashboard','A clear view of governance coverage, ownership and work requiring review.'],attention:['Governance Queue','Application gaps, assessments and pending governance decisions. Intake approvals stay in Access Portal.'],usage:['Usage & Activity','Automatically populated Zscaler usage evidence, observed identities and source freshness.'],health:['Inventory Health','Governance coverage, data quality and records needing maintenance.'],'intake-enrichment':['Portal Approval Queue','View requests, approved use cases and source history directly in Access Portal.'],'site-review':['Application Reviews','Resolve governance decisions, ownership, classification and missing application information.'],'approved-sites':['Approved Applications','Approved AI platforms and AI-enabled applications, with observed users and decision evidence.'],projects:['User Projects','Project groups, linked applications and recorded access.'],risk:['Risk Assessments','Review application data handling, NPI / PII exposure, controls and evidence.'],coverage:['App Coverage Gaps','Find missing ownership, purpose, classification, evidence and assessment answers.'],inventory:['AI Inventory','Master inventory of AI platforms and AI-enabled business applications.'],access:['Access Registry','Recorded users, access levels, subscriptions, ownership, SSO and project grants.'],requests:['Intake Requests','Open Access Portal for AI intake requests, approval progress and request history.'],discovery:['Discovery','Newly discovered applications, Shadow IT and source candidates requiring review.'],audit:['Audit Trail','Historical decisions, reviewer actions, evidence changes and project governance history.'],sources:['Classification & Sources','AI classifications, categories, source mappings, discovery evidence and vendor references.'],reports:['Executive Reports','Legal and InfoSec dashboards, governance summaries, coverage metrics and exports.']};
function workflowSection(view){return ['site-review','purpose-intake'].includes(view)?'attention':view==='health'?'reports':view==='intake-enrichment'?'requests':view;}
function workflowLinks(){const section=workflowSection(state.view),items=section==='attention'?[['attention','Governance Queue'],['purpose-intake','Business purpose intake'],['site-review','Application Reviews']]:section==='inventory'?[['inventory','AI Inventory'],['usage','Usage & Activity']]:section==='reports'?[['reports','Reports & exports'],['health','Inventory health']]:section==='requests'?[['requests','All Portal requests'],['intake-enrichment','Portal approval queue']]:[];return items.length?'<div class="workflow-links" role="navigation" aria-label="'+(section==='attention'?'Governance Queue views':section==='inventory'?'AI Inventory views':section==='reports'?'Executive Reports views':'Intake Requests views')+'">'+items.map(([view,label])=>'<a class="button '+(view===state.view?'primary':'')+'" href="#'+view+'" '+(view===state.view?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</div>':'';}
function reviewScopeNote(){if(state.view!=='site-review')return '';const id=new URLSearchParams(location.search).get('reviewApp');if(!id)return '';const app=state.apps.find(a=>Number(a.id)===Number(id));return note('Showing application reviews for '+esc(app?app.app_name:'an unmatched application')+'. <a href="/ai-governance.html#site-review">Show all application reviews</a>');}

const state={apps:[],requests:[],manual:[],grants:[],projects:[],links:[],audit:[],view:'dashboard',q:'',type:'',approval:'',risk:'',source:'',sort:{key:'',dir:1},useCases:{rows:[],error:''},admin:false,projectRead:false,projectError:'',save:null,editing:null,loaded:false,busy:false,zscaler:{sources:[],candidates:[],checked_at:null}};
const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=v=>String(v||'unknown').replace(/_/g,' ').replace(/^./,c=>c.toUpperCase());
const when=v=>{if(!v)return 'Not recorded';const raw=String(v),d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw+'T00:00:00':v);return Number.isFinite(d.getTime())?d.toLocaleDateString():'Unknown';};
const href=v=>{try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?esc(u.href):'';}catch{return '';}};
const evidence=v=>href(v)?`<a href="${href(v)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:'<span class="muted">Not recorded</span>';
const badge=(v,tone='')=>`<span class="badge ${tone}">${esc(human(v))}</span>`;
const appName=n=>(state.apps.find(a=>a.id===Number(n))||{}).app_name||'Unknown application';
const appButton=a=>`<button class="app-link" data-app="${Number(a.id)}">${esc(a.app_name)}</button>`;
const note=(s,w=false)=>`<div class="note${w?' warn':''}">${s}</div>`;
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
async function api(path,opts={}){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),opts.timeoutMs||20000);try{const r=await fetch(API+path,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})},signal:ctrl.signal});let d;try{d=await r.json();}catch{throw new Error('Unexpected response. Refresh the page and try again.');}if(!r.ok){const e=new Error(d.error||'Request failed');e.status=r.status;throw e;}return d;}catch(e){if(e.name==='AbortError')throw new Error('Request timed out. Reload to check whether the change was saved before trying again.');throw e;}finally{clearTimeout(timer);}}
function table(headers,rows,empty='No records yet'){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty"><strong>${esc(empty)}</strong></div></td></tr>`}</tbody></table></div>`;}
function panel(title,sub,body,actions=''){return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>${body}</section>`;}
function metrics(){const missing=state.apps.filter(a=>!a.owner||!a.category||!a.business_purpose||!a.evidence_url),embedded=state.apps.filter(a=>['embedded','both'].includes(a.ai_type));$('metrics').innerHTML=[['Applications',state.apps.length,'Catalog candidates and reviewed records'],['Embedded AI',embedded.length,'Explicitly classified applications'],['Needs completion',missing.length,'Owner, category, purpose or evidence']].map((m,i)=>`<div class="metric ${i===2&&m[1]?'warn':''}"><span>${m[0]}</span><strong>${m[1]}</strong><small>${m[2]}</small></div>`).join('')+'<div class="metric"><span>Intake requests</span><strong><a href="#requests">View intake ↗</a></strong><small>Requests and approvals are tracked in Access Portal</small></div>';}
function controls(){return `<div class="toolbar"><input id="filter-q" aria-label="Search inventory" placeholder="Search applications, owners or capabilities…" value="${esc(state.q)}"><select id="filter-type" aria-label="Filter AI type"><option value="">All AI types</option>${['standalone','embedded','both','unclassified'].map(x=>`<option value="${x}" ${state.type===x?'selected':''}>${human(x)}</option>`).join('')}</select><select id="filter-approval" aria-label="Filter approval"><option value="">All approval states</option>${['unreviewed','under_review','approved','restricted','rejected'].map(x=>`<option value="${x}" ${state.approval===x?'selected':''}>${human(x)}</option>`).join('')}</select><select id="filter-account" aria-label="Filter account arrangement"><option value="">All account arrangements</option>${['corporate','mixed','personal_only','unknown'].map(x=>`<option value="${x}" ${state.account===x?'selected':''}>${human(x)}</option>`).join('')}</select><select id="filter-sso" aria-label="Filter SSO provider"><option value="">All SSO providers</option>${['entra','okta','entra_and_okta','unknown'].map(x=>`<option value="${x}" ${state.sso===x?'selected':''}>${esc(ssoName(x))}</option>`).join('')}</select></div>`;}
function filtered(){const recent=state.view==='inventory'&&new URLSearchParams(location.search).get('catalogedWithin')==='30';return state.apps.filter(a=>(!recent||AIGovernanceOverviewModel.recentlyCataloged(a))&&(!state.q||[a.app_name,a.owner,a.vendor,a.capability_name,a.category,...(a.tags||[])].join(' ').toLowerCase().includes(state.q.toLowerCase()))&&(!state.type||(a.ai_type||'unclassified')===state.type)&&(!state.approval||(state.approval==='not_approved'?!approvedApp(a):(a.approval_status||'unreviewed')===state.approval))&&(!state.risk||(state.risk==='high')===highRisk(a).high)&&(!state.source||appSource(a)===state.source)&&(!state.account||((a.corporate_account||{}).account_type||'unknown')===state.account)&&(!state.sso||((a.corporate_account||{}).sso_provider||'unknown')===state.sso));}
function preferredSourceLabel(a){const p=AIGovernanceReports.provenance(a,state);return '<small>Preferred label: '+esc(p.preferred_label)+(p.source_category?' · '+esc(p.source_category):'')+'</small>';}
function usageUrl(id){return '/ai-governance.html'+(id?'?usageApp='+Number(id):'')+'#usage';}
function usageCell(a){const u=state.zscaler?.shadow_it,rows=(u?.rows||[]).filter(r=>Number(r.catalog_id)===Number(a.id)),end=(u?.window?.as_reported||[]).find(x=>/end/i.test(x.label));return '<a href="'+usageUrl(a.id)+'">Usage & observed users ↗</a>'+rows.map(r=>'<small>Shadow IT: '+esc(r.users==null?'Unknown':Number(r.users).toLocaleString())+' reported users · '+esc(r.transactions==null?'Unknown':Number(r.transactions).toLocaleString())+' transactions</small>').join('')+(rows.length?'<small>Report end: '+esc(end?.value||'Not supplied')+(u.retained?' · retained':'')+'</small>':'<small>No matched report aggregate · usage unknown</small>');}

function appRows(apps){return apps.map(a=>[`<div class="app-cell"><span class="app-mark" aria-hidden="true">${esc(a.app_name.slice(0,2).toUpperCase())}</span><div>${appButton(a)}<small>${esc(a.vendor||'Vendor not recorded')}</small><small>Source: ${esc(AIGovernanceReports.provenance(a,state).primary_source)}</small>${preferredSourceLabel(a)}</div></div>`,usageCell(a),`${esc(a.category||'Not classified')}<small>${esc(human(a.ai_type||'unclassified'))}${a.capability_name?' · '+esc(a.capability_name):''}</small>`,esc(a.owner||'Unassigned'),accountBadge(a)+directoryAccessCell(a),badge(a.approval_status||'unreviewed',a.approval_status==='approved'?'good':a.approval_status==='rejected'?'bad':'warn'),`${badge(a.enablement||'unknown')}<small>${a.linked_projects||0} project mapping(s)</small>`,`${evidence(a.evidence_url)}<small>${a.review_due?'Review '+when(a.review_due):'Review date not set'}</small>`]);}
function inventoryScope(){const parts=[];if(state.q)parts.push('Search: '+state.q);if(state.type)parts.push('AI type: '+human(state.type));if(state.approval)parts.push('Approval: '+human(state.approval));if(state.risk)parts.push(state.risk==='high'?'High risk only':'No high-risk trigger');if(state.source)parts.push('Source: '+sourceLabels[state.source]);if(state.account)parts.push('Account: '+human(state.account));if(state.sso)parts.push('SSO: '+ssoName(state.sso));return parts.join(' · ')||'All applications';}
function inventoryControls(){return `<div class="toolbar inventory-main-controls"><label>Find an application<input id="filter-q" aria-label="Search inventory" placeholder="Search applications, owners or capabilities…" value="${esc(state.q)}"></label><label>AI type<select id="filter-type" aria-label="Filter AI type"><option value="">All AI types</option>${['standalone','embedded','both','unclassified'].map(x=>`<option value="${x}" ${state.type===x?'selected':''}>${human(x)}</option>`).join('')}</select></label><label>Governance approval<select id="filter-approval" aria-label="Filter approval"><option value="">All approval states</option>${['approved','not_approved','unreviewed','under_review','restricted','rejected'].map(x=>`<option value="${x}" ${state.approval===x?'selected':''}>${x==='not_approved'?'Not approved (any)':human(x)}</option>`).join('')}</select></label><label>High risk<select id="filter-risk" aria-label="Filter high risk"><option value="">All applications</option><option value="high" ${state.risk==='high'?'selected':''}>High risk only</option><option value="none" ${state.risk==='none'?'selected':''}>No high-risk trigger</option></select></label><label>Source<select id="filter-source" aria-label="Filter source"><option value="">All sources</option>${Object.entries(sourceLabels).map(([k,l])=>`<option value="${k}" ${state.source===k?'selected':''}>${esc(l)}</option>`).join('')}</select></label></div><details class="inventory-filter-details" data-inventory-filters ${state.inventoryFiltersOpen?'open':''}><summary>Account and SSO filters</summary><div class="toolbar"><label>Account arrangement<select id="filter-account" aria-label="Filter account arrangement"><option value="">All account arrangements</option>${['corporate','mixed','personal_only','unknown'].map(x=>`<option value="${x}" ${state.account===x?'selected':''}>${human(x)}</option>`).join('')}</select></label><label>SSO provider<select id="filter-sso" aria-label="Filter SSO provider"><option value="">All SSO providers</option>${['entra','okta','entra_and_okta','unknown'].map(x=>`<option value="${x}" ${state.sso===x?'selected':''}>${esc(ssoName(x))}</option>`).join('')}</select></label></div></details><p id="inventory-scope" class="gov-coverage-note inventory-scope">${esc(inventoryScope())}</p>`;}
function inventoryDetail(a,p){return `<details class="queue-row-details inventory-row-details" data-inventory-details="${Number(a.id)}" ${state.inventoryDetails?.[a.id]?'open':''}><summary>Access, usage &amp; sources</summary><div><h3>Account &amp; access</h3>${accountBadge(a)}${directoryAccessCell(a)}<h3>Observed usage</h3>${usageCell(a)}<h3>Capability &amp; evidence</h3><small>AI capability: ${esc(a.capability_name||'Not recorded')}</small><small>Tenant feature enablement: ${esc(human(a.enablement||'unknown'))}</small><small>${Number(a.linked_projects)||0} project mapping(s)</small><small>Evidence / decision: ${evidence(a.evidence_url)}</small><small>Source category: ${esc(p.source_category||'Not recorded')}</small><small>Supporting: ${esc(p.other_sources||'No additional source recorded')}</small><small>Preferred source checked: ${esc(whenTime(p.source_checked_at))}</small><small>Source basis: ${esc(p.source_basis)}</small><button type="button" class="app-link" data-app="${Number(a.id)}">Open full record and evidence</button></div></details>`;}
// Consolidated inventory: High risk = app-level automatic check OR any linked workbook use case flagged.
const HIGH_FLAG='Review for High',sourceLabels={zscaler:'Zscaler',intake:'AI Use Case Intake',both:'Both',other:'Other / manual'};
const approvedApp=a=>(a.approval_status||'unreviewed')==='approved';
function appAssessment(a){const d=state.assessments?.ok?state.assessments.data:null;return d?(d.apps||[]).find(x=>Number(x.id)===Number(a.id))||null:null;}
function appUseCases(a){return (state.useCases?.rows||[]).filter(r=>Number(r.catalog_id)===Number(a.id));}
function highRisk(a){const r=appAssessment(a),auto=r?SharedAIInventory.automaticReview(r):null,cases=appUseCases(a).filter(u=>u.calc?.auto_flag===HIGH_FLAG);const reasons=[...(auto?auto.reasons:[]).map(x=>'App assessment: '+x),...cases.map(u=>'Use case '+(u.ref||u.id)+(u.profile?.name?' ('+u.profile.name+')':''))];return {high:reasons.length>0,reasons,auto};}
function appSource(a){const z=AIGovernanceReports.provenance(a,state).primary_source==='Zscaler',i=appUseCases(a).length>0;return z&&i?'both':z?'zscaler':i?'intake':'other';}
const highRiskBadge=h=>h.high?`<span class="badge high-risk" title="${esc(h.reasons.join('; '))}">High risk</span>`:'<span class="muted">—</span>';
const approvalBadge=a=>approvedApp(a)?badge('Approved','good'):badge('Not approved',a.approval_status==='rejected'?'bad':'warn');
const invCols=[['name','Application / source'],['risk','High risk'],['source','Source'],['approval','Approval'],['category','AI classification'],['owner','Owner & business purpose'],['','Details']];
function sortValue(a,k){return k==='risk'?(highRisk(a).high?0:1):k==='source'?['both','intake','zscaler','other'].indexOf(appSource(a)):k==='approval'?(approvedApp(a)?0:1):k==='category'?(a.category||'￿'):k==='owner'?(a.owner||'￿'):(a.app_name||'');}
function sortApps(apps){const {key,dir}=state.sort;if(!key)return apps;return apps.slice().sort((x,y)=>{const a=sortValue(x,key),b=sortValue(y,key);return ((typeof a==='number'?a-b:String(a).localeCompare(String(b)))*dir)||String(x.app_name).localeCompare(String(y.app_name));});}
function inventoryTable(apps){const rows=inventoryRows(apps),s=state.sort;return `<div class="table-scroll"><table><thead><tr>${invCols.map(([k,l])=>k?`<th scope="col" aria-sort="${s.key===k?(s.dir>0?'ascending':'descending'):'none'}"><button type="button" class="sort-head" data-sort="${k}">${esc(l)}<span aria-hidden="true">${s.key===k?(s.dir>0?'▲':'▼'):'↕'}</span></button></th>`:`<th scope="col">${esc(l)}</th>`).join('')}</tr></thead><tbody>${apps.length?apps.map((a,i)=>{const r=rows[i];return `<tr class="inventory-row" data-row-app="${Number(a.id)}"><td>${r[0]}</td><td>${highRiskBadge(highRisk(a))}</td><td>${badge(sourceLabels[appSource(a)])}</td><td>${approvalBadge(a)}<small>${esc(human(a.approval_status||'unreviewed'))}${a.review_due?' · Review '+esc(when(a.review_due)):''}</small></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[4]}</td></tr>`;}).join(''):`<tr><td colspan="${invCols.length}"><div class="empty"><strong>No applications match these filters</strong></div></td></tr>`}</tbody></table></div>`;}
function approvalSummary(){const all=state.apps,ok=all.filter(approvedApp).length,pct=all.length?Math.round(ok/all.length*100):0,rest=['under_review','unreviewed','restricted','rejected'].map(x=>[x,all.filter(a=>(a.approval_status||'unreviewed')===x).length]).filter(x=>x[1]),hr=all.filter(a=>highRisk(a).high).length;return `<section class="approval-summary" aria-label="Approval summary"><div class="approval-tiles"><button type="button" class="approval-tile good" data-approval-pick="approved" aria-pressed="${state.approval==='approved'}"><strong>${ok}</strong><span>Approved</span></button><button type="button" class="approval-tile warn" data-approval-pick="not_approved" aria-pressed="${state.approval==='not_approved'}"><strong>${all.length-ok}</strong><span>Not approved</span></button><button type="button" class="approval-tile bad" data-risk-pick="high" aria-pressed="${state.risk==='high'}"><strong>${hr}</strong><span>High risk</span></button></div><div class="approval-chart"><div class="approval-bar" role="img" aria-label="${ok} of ${all.length} applications approved"><span style="width:${pct}%"></span></div><p>${pct}% approved of ${all.length} applications${rest.length?' · Not approved: '+rest.map(([x,n])=>esc(human(x))+' '+n).join(' · '):''}</p></div></section>`;}
function riskSection(a){const r=appAssessment(a),h=highRisk(a),cases=appUseCases(a),fields=state.assessments?.ok?state.assessments.data.fields||[]:[];let body='';if(!state.assessments?.ok)body=note('Risk assessment data is unavailable: '+esc(state.assessments?.error||'not read'),true);else if(!r)body='<p class="muted">No application-level risk assessment is recorded.</p>';else{const x=r.assessment,sections=[...new Set(fields.map(f=>f.section))];body=`<dl class="risk-facts"><div><dt>High risk</dt><dd>${highRiskBadge(h)}${h.high?'<span class="risk-reasons">'+esc(h.reasons.join(' · '))+'</span>':h.auto?.unknown?'<span class="risk-reasons">Some trigger answers are still unknown</span>':''}</dd></div><div><dt>Reviewed tier</dt><dd>${esc(x.tier||'Not assigned')}</dd></div><div><dt>Review status</dt><dd>${esc(x.review_status||'Not recorded')}</dd></div><div><dt>Next review</dt><dd>${esc(x.next_review||'Not set')}${x.overdue?' · Overdue':''}</dd></div><div><dt>Required answers missing</dt><dd>${Number(x.required_gaps)||0}</dd></div><div><dt>Control follow-up</dt><dd>${(x.control_gaps||[]).length}</dd></div></dl>`+sections.map(sec=>{const items=fields.filter(f=>f.section===sec).map(f=>[f,(x.coverage||[]).find(c=>c.key===f.key)]).filter(([,c])=>c);return items.length?`<h4>${esc(sec)}</h4><dl class="risk-answers">${items.map(([f,c])=>`<div><dt>${esc(f.label)}</dt><dd class="${c.state==='available'?'':'muted'}">${esc(c.state==='available'?c.value:c.value||'Unknown')}${c.control_gap?' '+badge('Follow-up','warn'):''}</dd></div>`).join('')}</dl>`:'';}).join('');}const uc=state.useCases?.error?note('Workbook use cases unavailable: '+esc(state.useCases.error),true):cases.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Use case</th><th scope="col">Status</th><th scope="col">Auto-flag</th><th scope="col">Risk tier</th><th scope="col">Next review</th></tr></thead><tbody>${cases.map(u=>`<tr><td><strong>${esc(u.ref||'')}</strong> ${esc(u.profile?.name||'')}<small>${esc(u.profile?.dept||'')}</small></td><td>${esc(u.profile?.status||'Not recorded')}</td><td>${u.calc?.auto_flag===HIGH_FLAG?badge(HIGH_FLAG,'bad'):'—'}</td><td>${esc(u.profile?.tier||'Not assigned')}</td><td>${esc(u.calc?.next_review||'Not set')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No use cases from the InfoSec / Legal workbook are linked to this application.</p>';return `<section class="app-risk" aria-label="Risk assessment"><h3>Risk assessment</h3>${body}${state.admin?`<p><button type="button" class="button" data-app-risk="${Number(a.id)}">Edit risk assessment</button></p>`:''}<h3>Use cases · InfoSec / Legal workbook (${cases.length})</h3>${uc}</section>`;}
function appGlance(a){return `<dl class="app-glance"><div><dt>High risk</dt><dd>${highRiskBadge(highRisk(a))}</dd></div><div><dt>Source</dt><dd>${badge(sourceLabels[appSource(a)])}</dd></div><div><dt>Approval</dt><dd>${approvalBadge(a)}</dd></div><div><dt>Reviewed tier</dt><dd>${esc(appAssessment(a)?.assessment?.tier||'Not assigned')}</dd></div></dl>`;}
function inventoryRows(apps){return apps.map(a=>{const p=AIGovernanceReports.provenance(a,state),corporate=['corporate','mixed'].includes(a.corporate_account?.account_type);return [`<div class="app-cell"><span class="app-mark" aria-hidden="true">${esc(a.app_name.slice(0,2).toUpperCase())}</span><div>${appButton(a)}${a.vendor?'<small>'+esc(a.vendor)+'</small>':''}<small>${esc(p.primary_source)} / ${esc(p.preferred_label)}</small>${corporate?badge(a.corporate_account.account_type,'good'):''}</div></div>`,`${esc(a.category||'Not classified')}<small>${esc(human(a.ai_type||'unclassified'))}</small>`,`<strong>${esc(a.owner||'Owner not recorded')}</strong><small class="inventory-purpose">Purpose: ${esc(a.business_purpose||'Not recorded')}</small>`,`${badge(a.approval_status||'unreviewed',a.approval_status==='approved'?'good':a.approval_status==='rejected'?'bad':'warn')}<small>${a.review_due?'Review '+esc(when(a.review_due)):'Review date not set'}</small>`,inventoryDetail(a,p)];});}
function discoveryCandidate(a){return !a.category||!a.owner||!a.evidence_url||(a.approval_status||'unreviewed')==='unreviewed';}
function discoveryReviewFocus(a){const gaps=[];if(!a.category)gaps.push('AI classification');if(!a.owner)gaps.push('Business owner');if(!a.business_purpose)gaps.push('Business purpose');if(!a.evidence_url)gaps.push('Review evidence');if((a.approval_status||'unreviewed')==='unreviewed')gaps.push('Governance review');return gaps;}
function discoveryRows(apps){return apps.map(a=>{const row=inventoryRows([a])[0];return [row[0],'<small class="discovery-review-focus">'+discoveryReviewFocus(a).map(esc).join(' · ')+'</small>',row[2],row[3],'<button type="button" class="button" data-app="'+Number(a.id)+'" aria-label="Review '+esc(a.app_name)+'">Review candidate</button>'+row[4]];});}
function discoverySources(){const z=state.zscaler||{},sources=z.sources||[];const warnings=sources.filter(x=>x.status!==200||x.partial).map(x=>x.name+': '+(x.status===200?'partial read':x.status===403?'read denied':x.status?'HTTP '+x.status:'unavailable'));return '<div class="discovery-source-context"><p class="gov-coverage-note">Zscaler sources: '+(z.checked_at?'collected '+esc(whenTime(z.checked_at)):'not yet checked')+'. '+esc(warnings.join(' · '))+'</p>'+(z.shadow_it?.retained?note('Shadow IT evidence is retained from '+esc(whenTime(z.shadow_it.checked_at))+'. The latest report did not refresh this evidence.',true):'')+(z.error?note(esc(z.error),true):'')+'<details class="discovery-source-details" data-report-details="discoverySources" '+(state.reportDetails?.discoverySources?'open':'')+'><summary>Vendor candidates, Shadow IT usage &amp; source details</summary><div>'+zscalerPanel()+'</div></details></div>';}
function discoveryPage(){const apps=filtered().filter(discoveryCandidate);return note('Review candidate applications and their missing information. Discovery does not establish approval, active AI-feature use or entitlement. Zscaler is primary where matched; supporting evidence remains available. Vendor change monitoring is not connected yet.')+discoverySources()+'<div class="discovery-candidates">'+panel('Discovery candidates',`${apps.length} matching records · standalone and embedded AI`,inventoryControls()+`<div id="app-results">${inventoryResults(apps)}</div>`+'<div class="panel-bottom">Existing catalog candidates requiring classification, ownership, evidence or governance review. Open a candidate to review its recorded information; no decision is made automatically.</div>')+'</div>';}
function inventoryResults(apps){if(state.view==='discovery')return '<div class="discovery-main-table">'+table(['Candidate / source','Review focus','Owner & business purpose','Governance','Review / details'],discoveryRows(apps),'No candidates match these filters')+'</div>';return state.view==='inventory'?'<div class="inventory-main-table">'+inventoryTable(sortApps(apps))+'</div>':table(['Application','Observed usage','Classification','Owner','Account / SSO / access','Governance','AI enablement','Evidence'],appRows(apps),'No applications match these filters');}
function inventoryDisclosure(title,body){return body?'<details class="inventory-record-details full"><summary>'+esc(title)+'</summary><div>'+body+'</div></details>':'';}
function inventory(discovery=false){if(discovery)return discoveryPage();let apps=filtered();if(discovery)apps=apps.filter(a=>!a.category||!a.owner||!a.evidence_url||(a.approval_status||'unreviewed')==='unreviewed');const msg=discovery?'Discovery identifies candidate applications; it does not establish governance approval, active use or AI feature enablement. Vendor change monitoring is not connected yet.':'Known applications are candidates until reviewed. Observed traffic does not establish AI-feature use or approval. Zscaler is primary where matched; supporting evidence remains available in each record.';return (state.view==='inventory'&&new URLSearchParams(location.search).get('catalogedWithin')==='30'?note('Showing applications first cataloged in the past 30 days. This is not a vendor AI-feature release date. <a href="/ai-governance.html#inventory">Show all inventory ↗</a>'):'')+(discovery?zscalerPanel()+'<div class="section-space"></div>':approvalSummary())+note(esc(msg))+panel(discovery?'Discovery candidates':'Applications',`${apps.length} matching records · standalone and embedded AI`,(discovery?controls():inventoryControls())+`<div id="app-results">${inventoryResults(apps)}</div>`+`<div class="panel-bottom">Source: existing AI catalog + governance records. ${discovery?'Automated discovery does not approve an application.':'Select an application to review its capabilities, purpose and linked projects.'}</div>`);}
function zscalerPanel(){const z=state.zscaler||{},sources=z.sources||[],candidates=z.candidates||[];return panel('Zscaler discovery evidence',z.checked_at?'Last checked '+new Date(z.checked_at).toLocaleString():'No Zscaler source check recorded',note('Vendor AI definitions identify candidates. Rule references show configuration, not effective access. The Shadow IT report has a separate permission check.')+(z.error?note(esc(z.error),true):'')+`<div class="connection-list">${sources.map(x=>`<div class="connection"><div><strong>${esc(x.name)}</strong><p>${esc(x.note)}${x.count!=null?' · '+x.count+' returned':''}</p></div>${badge(x.status===200?(x.partial?'Partial read':'Read available'):x.status===403?'Read denied':x.status?'HTTP '+x.status:'Unavailable',x.status===200&&!x.partial?'good':'warn')}</div>`).join('')}</div>`,state.admin?'<button class="button" data-check-zscaler>Check Zscaler sources</button>':'')+'<div class="section-space"></div>'+shadowUsagePanel()+'<div class="section-space"></div>'+panel('Vendor AI definitions','Definitions and policy references; separate from observed traffic',''+(candidates.length?`<div class="toolbar"><input id="zscaler-filter" aria-label="Filter Zscaler candidates" placeholder="Filter vendor AI definitions…"></div><div id="zscaler-results">${zscalerRows(candidates)}</div>`:empty('No vendor candidates loaded','Check the available Zscaler sources to collect definitions and policy references.')));}
function zscalerRows(items){return table(['Vendor AI application','Definition code','Policy references','Inventory'],items.slice(0,200).map(a=>[esc(a.name)+`<small>${esc(a.parent)}</small>`,esc(a.code),a.rules&&a.rules.length?a.rules.map(r=>`<small>${esc(r.name)} · ${esc(r.state)} · ${esc((r.actions||[]).join(', '))}</small>`).join(''):'No explicit app reference in returned rules',a.catalog_id?`<button class="app-link" data-app="${a.catalog_id}">Open inventory record</button>`:state.admin?`<button class="button small" data-import-zscaler="${esc(a.code)}">Import candidate</button>`:'Not in inventory']),'No matching vendor definitions')+(items.length>200?'<div class="panel-bottom">Showing the first 200 matches. Refine the filter.</div>':'');}
function shadowUsageItems(){const u=(state.zscaler||{}).shadow_it;if(!u)return [];const q=(state.shadowq||'').toLowerCase();return (u.rows||[]).filter(x=>(state.shadowScope==='all'||x.ai_relevant)&&(!q||[x.name,x.category,x.sanction].join(' ').toLowerCase().includes(q)));}
function shadowUsageRows(items){return table(['Observed application','Reported users','Transactions','Data consumed (reported)','Vendor risk / sanction','Last used (reported)','Inventory'],items.slice(0,200).map(x=>[esc(x.name)+`<small>${esc(x.category||'Category not supplied')}</small>`,x.users==null?'Unknown':esc(x.users.toLocaleString()),x.transactions==null?'Unknown':esc(x.transactions.toLocaleString()),esc(x.data_consumed||'Not supplied')+(x.upload||x.download?`<small>Upload ${esc(x.upload||'not supplied')} · Download ${esc(x.download||'not supplied')}</small>`:''),esc(x.risk||'Risk not supplied')+`<small>${esc(x.sanction||'Sanction label not supplied')}</small>`,esc(x.last_used||'Not supplied'),x.catalog_id?`<button class="app-link" data-app="${Number(x.catalog_id)}">Open inventory record</button>`:'Not matched to inventory']),'No matching application usage')+(items.length>200?`<div class="panel-bottom">Showing 200 of ${items.length} matching rows. Refine the filter or download all shown-scope rows.</div>`:'');}
function shadowPeriodNote(u){const period=(u.window?.as_reported||[]).map(x=>x.label+': '+x.value).join(' · ');return note(period?'Vendor report period: '+esc(period)+'. Retrieval time is separate from the report’s coverage.':'Vendor report period not supplied. Requested LAST_7_DAYS; collection time does not establish event recency.');}
function shadowUsagePanel(){const z=state.zscaler||{},u=z.shadow_it;if(!u)return panel('Shadow IT application usage','No detailed usage snapshot collected',note(z.error?esc(z.error):(state.admin?'Run Check Zscaler sources to import the application usage report.':'An administrator can refresh Zscaler sources to collect application usage.')+' A denied, throttled or invalid read does not establish zero usage.',true));const items=shadowUsageItems();return panel('Shadow IT application usage',`Seven-day report · Collected ${new Date(u.checked_at).toLocaleString()} · ${u.rows.length.toLocaleString()} application rows`,(u.retained?note('The latest report was unavailable. Showing retained usage collected '+esc(new Date(u.checked_at).toLocaleString())+'. This evidence was not refreshed.',true):'')+shadowPeriodNote(u)+note('Observed application traffic is separate from AI-feature use, licensed seats, access grants and governance approval. User counts can overlap across applications. Risk and sanction labels below are reported by Zscaler.')+`<div class="toolbar"><input id="shadow-it-filter" aria-label="Filter Shadow IT usage" placeholder="Filter observed applications, categories or sanction labels…" value="${esc(state.shadowq||'')}"><select id="shadow-it-scope" aria-label="Shadow IT usage scope"><option value="ai" ${state.shadowScope!=='all'?'selected':''}>AI-related applications</option><option value="all" ${state.shadowScope==='all'?'selected':''}>All observed applications</option></select></div><div id="shadow-it-results">${shadowUsageRows(items)}</div><div class="panel-bottom">AI-related includes vendor AI categories, checked AI definitions and exact inventory matches. Vendor category is separate from Legal’s recorded classification. Missing fields remain unknown.</div>`,`<button class="button" data-export-shadow-it>Download shown usage CSV</button>`);}
function shadowUsageForApp(a){const u=(state.zscaler||{}).shadow_it;if(!a.id||!u)return '';const rows=u.rows.filter(x=>Number(x.catalog_id)===Number(a.id));return `<div class="section-space"><h3>Shadow IT application usage</h3><p>Seven-day report · Collected ${esc(new Date(u.checked_at).toLocaleString())}${u.retained?' · Retained after an unavailable report read':''}</p>`+shadowPeriodNote(u)+note('Application traffic does not establish an AI feature was used, an entitlement was granted or governance approval was given.')+(rows.length?shadowUsageRows(rows):'<p>No matching application aggregate in the returned report. This does not establish absence of usage outside its window or coverage.</p>')+'</div>';}
function downloadShadowUsage(){try{const r=AIGovernanceReports.build(state,{});r.shadowRows=shadowUsageItems();r.filter={...r.filter,shadow_scope:state.shadowScope==='all'?'All observed applications':'AI-related applications',shadow_query:state.shadowq||''};saveBlob(AIGovernanceReports.csv('shadow_it',r),'text/csv;charset=utf-8','ai-governance-shadow-it-'+new Date().toLocaleDateString('en-CA')+'.csv');}catch(e){toast(e.message);}}

function projectUrl(n){return `/ai-governance.html?project=${Number(n)}#projects`;}
function accessDisclosure(key,title,body){return `<details class="access-details" data-access-details="${esc(key)}" ${state.accessDetails?.[key]?'open':''}><summary>${esc(title)}</summary><div>${body}</div></details>`;}
function accessApplication(id,name){const app=state.apps.find(a=>Number(a.id)===Number(id)),p=app?AIGovernanceReports.provenance(app,state):null;return `<button class="app-link" data-app="${Number(id)}">${esc(name)}</button><small>${p?esc(p.primary_source)+' / '+esc(p.preferred_label):'Source not established'}</small>`;}
function directoryRegistry(){const r=AIGovernanceReports.build(state,{}),d=state.identityAccess||{};if(!r.identityRead)return identityAccessPanel(r);const basis=x=>[x.direct_assignment_users>0?'Direct assignment':'',x.group_membership_users>0?'Direct group membership':'',x.license_assigned_users>0?'License assignment':'',x.okta_assignment_users>0?'Okta app assignment':''].filter(Boolean).join(' · ')||'Evidence not established';
 const warnings=(d.retained?note('Latest attempt was incomplete. Retaining evidence collected '+esc(whenTime(d.checked_at))+'. Latest attempt '+esc(whenTime(d.last_attempt?.checked_at))+'.',true):d.status==='partial'?note('Access coverage is partial; counts are lower bounds and missing evidence remains unknown.',true):'')+(state.partial?note('Some governance reads are incomplete. Refresh saved evidence before exporting.',true):'');
 const rows=r.identityRows.map(x=>[appButton(x.app)+'<small>'+esc(x.app.provenance.primary_source)+' / '+esc(x.app.provenance.preferred_label)+'</small>',esc(x.provider),'<strong>'+Number(x.user_count)+'</strong>'+(x.disabled_user_accounts?'<small class="access-status-warning">'+Number(x.disabled_user_accounts)+' known disabled</small>':'')+(x.account_status_unknown?'<small>'+Number(x.account_status_unknown)+' account status unknown</small>':''),esc(basis(x)),`<button type="button" class="app-link" data-identity-app="${Number(x.catalog_id)}">Review users &amp; evidence</button>`+accessDisclosure('directory-'+x.catalog_id+'-'+x.provider,'Assignment and source details',
 '<small>'+(x.provider==='Entra'?'Direct '+Number(x.direct_assignment_users)+' · group members '+Number(x.group_membership_users)+' · licenses '+Number(x.license_assigned_users):'Okta app assignments '+Number(x.okta_assignment_users))+'</small><small>Overlapping evidence; not additive</small><small>'+Number(x.disabled_user_accounts)+' known disabled · '+Number(x.account_status_unknown)+' account status unknown</small><small>'+Number(x.active_instances)+' active · '+Number(x.inactive_instances)+' inactive app instances</small><small>'+Number(x.inactive_only_users)+' inactive-only accounts excluded</small><small>Supporting: '+esc(x.app.provenance.other_sources||'No additional source recorded')+'</small><small>Access evidence provider: '+esc(x.provider)+'</small><small>Collected '+esc(whenTime(d.checked_at))+' · '+esc(d.status)+(d.retained?' · Retained':'')+'</small><small>Run '+esc(d.run_id)+'</small>')]);
 const methods=accessDisclosure('directory-methods','Collection notes and user export',note('Counts are distinct accounts per application and provider across active app instances. Direct assignments, direct group members and licenses overlap; do not add subtype counts or sum Entra and Okta as unique people. Disabled accounts can retain assignments. Inactive-only assignments remain in user evidence but are excluded from summary counts. Grant dates and AI-feature entitlement require separate evidence. User details and exports require the existing AI Governance and Identity Diagnostics read permissions.')+'<p>Collected '+esc(whenTime(d.checked_at))+' · Run '+esc(d.run_id)+'. Other providers and observed activity keep their original attribution and dates.</p><button class="button" data-identity-export-all '+(state.partial?'disabled':'')+'>Download user access CSV</button>');
 return panel('Directory & license access evidence',r.identityRows.length+' application/provider groups · Collected '+whenTime(d.checked_at)+' · '+d.status+(d.retained?' · Retained':''),warnings+note('Accounts are distinct per application and provider. Keep Entra and Okta separate; evidence types overlap. Assignment or activity does not establish original grant dates or AI-feature entitlement.')+'<div class="access-directory-table">'+table(['Application / primary label','Provider','Distinct accounts','Access evidence','Review'],rows,'No exact app matches in this report scope')+'</div><div class="access-methods">'+methods+'</div>',`<button class="button" data-export="identity_access" ${state.partial?'disabled':''}>Download access summary CSV</button>`);
}
function access(){const available=state.projects.filter(p=>p.status==='active'),projectScope=new URLSearchParams(location.search).get('project'),scopedGrants=projectScope?state.grants.filter(g=>g.project_id===Number(projectScope)):state.grants;
 const mapped=scopedGrants.map(g=>[esc(g.user_display_name||g.user_identity)+`<small>${esc(g.user_identity)}${g.user_dept?' · '+esc(g.user_dept):''}</small>`,accessApplication(g.catalog_id,g.app_name),esc(g.access_level)+`<small>${esc(g.subscription_type||'Subscription not specified')}</small><small>Mapped purpose: ${esc(g.mapped_purpose||'Not recorded')}</small>`,badge(g.ad_action_on_add==='failed'?'AD add failed':g.status,g.ad_action_on_add==='failed'?'bad':'')+`<small>${g.expires_at?'Expiry '+esc(when(g.expires_at)):'No expiry recorded'}</small>`,`Recorded event: ${esc(when(g.earliest_recorded_event))}<small>Original vendor grant date unknown</small>`,accessDisclosure('project-grant-'+g.link_id+'-'+g.grant_id,'Project and evidence details',`<a href="${projectUrl(g.project_id)}">${esc(g.project_name)} ↗</a><small>${esc(g.ad_group_name)}</small><small>${esc(g.capability_name||'Application-level mapping')}</small><small>Latest grant update: ${esc(when(g.latest_grant_update))}</small><small>Evidence: ${evidence(g.evidence_url)}</small>`)]);
 const manual=state.manual.map(a=>[esc(a.user_identity),accessApplication(a.catalog_id,a.app_name),esc(a.access_level)+`<small>${esc(a.subscription_type||'Subscription not specified')}</small><small>Purpose: ${esc(a.business_purpose||'Not recorded')}</small>`,badge(a.status),a.granted_at?esc(when(a.granted_at)):'Unknown',accessDisclosure('manual-'+a.id,'Record and evidence details',`<small>${esc(a.capability_name||'Application-level record')}</small><small>Evidence: ${evidence(a.evidence_url)}</small><small>Recorded by ${esc(a.recorded_by)}</small>${a.status==='recorded'&&state.admin?`<button type="button" class="app-link" data-close-access="${a.id}">Close record</button>`:''}`)]);
 const projects=state.projectRead?accessDisclosure('project-administration','Project mapping administration',panel('Connected User Projects',`${new Set(available.map(p=>p.id)).size} active projects · map the application and access each group enables`,table(['Project','Recorded business description','Existing group','Governance mapping'],available.map(p=>[`<a href="${projectUrl(p.id)}">${esc(p.name)} ↗</a>`,esc(p.description||'Not recorded'),esc(p.ad_group_name||'No group linked'),state.admin&&p.ad_group_name?`<button class="button small" data-link-project="${p.id}">Link application</button>`:'Review project']),'No active User Projects'))):'';
 return '<div class="access-registry">'+directoryRegistry()+'<p class="gov-coverage-note access-activity-link"><a href="'+usageUrl()+'">Observed usage &amp; users ↗</a> · Activity is separate from directory evidence and recorded grants. Zscaler stays primary where matched; supporting sources remain attributed.</p>'+(projectScope?note('Showing mapped grants for project #'+Number(projectScope)+'. <a href="/ai-governance.html#access">Show all projects</a>'):'')+
 panel('Linked project grants',state.projectRead?`${mapped.length} returned rows · recorded group grants, separate from current vendor seats`:'User Projects permission is required to view linked grants',state.projectRead?table(['User','Application / primary label','Access / mapped purpose','Recorded state','Recorded date','Details'],mapped,'No project mappings yet'):empty('Project access unavailable',state.projectError||'Ask an administrator for User Projects read access.'),state.admin&&state.projectRead?'<button class="button" data-action="link">Link a project</button>':'')+'<div class="section-space"></div>'+
 panel('Other access records',`${manual.length} evidence-backed manual records · maximum 2,000 returned`,table(['User','Application / primary label','Access / purpose','Record state','Original grant date','Details'],manual,'No additional access records'),state.admin?'<button class="button" data-action="access">Record access</button>':'')+'<div class="access-project-administration">'+projects+'</div></div>';
}

function empty(t,s){return `<div class="empty"><strong>${esc(t)}</strong><p>${esc(s)}</p></div>`;}
function intakeTiles(){
 const href=(location.hostname.startsWith('dev-')?'https://dev-accessportal.nrpi.local':'https://accessportal.nrpi.local')+'/api/portal/identity/start?mode=signin&next=%2F%3Fintake%3Daia';
 const flow=steps=>'<ol class="intake-flow">'+steps.map(t=>'<li>'+t+'</li>').join('')+'</ol>';
 const art='<svg width="180" height="88" viewBox="0 0 180 88" aria-hidden="true"><g stroke="#b9a1ff" stroke-width="1.5" fill="none"><path d="M24 28 65 12 105 33 65 49 24 28 24 67 65 49 105 70 65 82 24 67M65 12V82M105 33V70"/></g><g fill="#b9a1ff"><circle cx="24" cy="28" r="6"/><circle cx="65" cy="12" r="6"/><circle cx="105" cy="33" r="6"/><circle cx="65" cy="49" r="6"/><circle cx="24" cy="67" r="6"/><circle cx="65" cy="82" r="6"/><circle cx="105" cy="70" r="6"/></g><rect x="134" y="22" width="35" height="55" rx="7" fill="#8148d8" stroke="#b9a1ff"/><path d="M143 36h17M143 48h17M143 60h10" stroke="#d4c5ff" stroke-width="4"/></svg>';
 return note('<strong>AI intake is handled in Access Portal.</strong> Open its existing AI intake chooser in a new tab. Submission and approval stay in Access Portal.')+
 '<section class="intake-tiles" aria-label="AI intake"><article class="panel intake-tile"><div class="intake-banner">'+art+'<span>Request · Approval workflow</span></div><div class="intake-body"><h2>New AI Use Case</h2><p>Propose a new AI solution, automation, integration, agent, or any AI use that a business process will depend on. Reviewed and approved through the AI Use Case workflow.</p>'+flow(['Request','Review','Approval','Notification'])+'<a class="button intake-cta" href="'+href+'" target="_blank" rel="noopener">Start New AI Use Case ↗</a></div></article></section>';
}
function requests(){return '<div id="maintenance-view"></div>'+intakeTiles();}
function auditEntries(){const all=state.audit.map(a=>({...a,source:'Governance',detailKey:'data-audit'})).concat((state.projectAudit||[]).map(a=>({...a,source:'User Projects',app_name:state.links.filter(l=>l.project_id===a.project_id).map(l=>l.app_name).join(', '),detailKey:'data-project-audit'})));return all.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).filter(a=>(!state.auditSource||a.source===state.auditSource)&&(!state.auditQuery||[a.actor,a.action,a.app_name,a.project_name,a.user_identity].join(' ').toLowerCase().includes(state.auditQuery.toLowerCase())));}
function auditOperational(a){return a.source==='Governance'&&(String(a.action||'').startsWith('source_refresh_')||['identity_access_snapshot_saved','metadata_quality_sampled','rapid7_historical_links_reconciled','rapid7_catalog_links_reconciled','rapid7_evidence_collected','rapid7_collection_requested','enterprise_sources_checked','zscaler_sources_checked'].includes(a.action));}
function auditRecordedDecision(a){let value=a.after_json;if(typeof value==='string'){try{value=JSON.parse(value);}catch{return '';}}return value&&typeof value==='object'&&!Array.isArray(value)&&typeof value.approval_status==='string'&&value.approval_status.trim()?'<small>Recorded approval: '+esc(human(value.approval_status))+'</small>':'';}
function auditMappedApps(a){const ids=a.source==='Governance'?[Number(a.catalog_id)]:(state.links||[]).filter(l=>Number(l.project_id)===Number(a.project_id)).map(l=>Number(l.catalog_id));return (state.apps||[]).filter(x=>ids.includes(Number(x.id)));}
function auditSourceDetails(apps){return apps.length?'<details class="audit-source-details"><summary>Current source context</summary><div><small>Current inventory mappings and source evidence; separate from this historical event.</small>'+apps.map(a=>{const p=AIGovernanceReports.provenance(a,state);return '<strong>'+esc(a.app_name)+'</strong><small>'+esc(p.primary_source+' / '+p.preferred_label)+'</small><small>Supporting: '+esc(p.other_sources||'No additional source recorded')+'</small><small>Preferred source collected: '+esc(whenTime(p.source_checked_at))+'</small><small>Source basis: '+esc(p.source_basis||'Not recorded')+'</small>';}).join('')+'</div></details>':'';}
function auditRows(entries){return entries.map(a=>{const apps=auditMappedApps(a),single=a.source==='Governance'&&apps.length===1?AIGovernanceReports.provenance(apps[0],state):null;return [new Date(a.created_at).toLocaleString(),esc(human(a.action))+`<small>${esc(a.source)} event</small>`+auditRecordedDecision(a),esc(a.app_name||a.project_name||'Not linked')+`<small>${esc(a.user_identity||'')}</small>`+(single?'<small>Current inventory: '+esc(single.primary_source+' / '+single.preferred_label)+'</small>':''),esc(a.actor||'Not recorded'),`<button type="button" class="app-link" ${a.detailKey}="${Number(a.id)}">View recorded event</button>`+auditSourceDetails(apps)];});}
function auditResults(){const entries=auditEntries(),history=entries.filter(a=>!auditOperational(a)),operations=entries.filter(auditOperational),headers=['When','Decision / review event','Application / project','Recorded by','Evidence / details'];return '<p class="audit-scope" role="status">'+history.length+' matching decisions and review-history events; '+operations.length+' collection and system events in optional details.</p><details class="audit-operations" data-report-details="auditOperations" '+(state.reportDetails?.auditOperations?'open':'')+'><summary>Collection &amp; system events ('+operations.length+')</summary><div><p>Routine collection, source checks and reconciliation events retain their original actor, date and recorded evidence. These events are separate from application approval.</p>'+table(headers,auditRows(operations),'No collection or system events match these filters')+'</div></details><div class="audit-history-table">'+table(headers,auditRows(history),'No decisions or review-history events match these filters')+'</div>';}

function audit(){return panel('Decisions &amp; review history',`${state.audit.length} governance events · ${(state.projectAudit||[]).length} project events returned · up to 500 from each source`,`<div class="toolbar audit-controls"><label>Find a recorded event<input id="audit-query" aria-label="Search audit trail" placeholder="Actor, application, project or event…" value="${esc(state.auditQuery||'')}"></label><label>Event source<select id="audit-source" aria-label="Audit source">${['','Governance','User Projects'].map(x=>`<option value="${x}" ${state.auditSource===x?'selected':''}>${x||'All sources'}</option>`).join('')}</select></label></div><div id="audit-results">${auditResults()}</div><div class="panel-bottom">Newest recorded events first. Recorded decisions and before/after evidence are historical; current application labels are identified separately. Zscaler remains primary where positively matched, with supporting source evidence available.</div>`)+(state.projectAuditError?note('Project audit unavailable: '+esc(state.projectAuditError),true):'')+'<details class="audit-methods"><summary>History scope and evidence notes</summary><div>'+note('Governance edits and assessment saves retain their before/after values. User Projects events retain their original actor, time, grant reference and details. Application-to-project context uses recorded mappings; it does not establish live access. Search and event-source filters apply to both lists. Returned history is limited to up to 500 events from each source; it is not an exhaustive audit archive.')+'</div></details>';}
// Project browsing keeps recorded evidence separate from live entitlements.
const PROJECT_PAGE_SIZE=12;
function projectScope(){return Number(new URLSearchParams(location.search).get('project'))||null;}
function scopedProjects(){const all=[...new Map(state.projects.map(p=>[p.id,p])).values()];return all.filter(p=>!projectScope()||p.id===projectScope());}
function projectFilter(){return state.projectStatus||(projectScope()?'all':'active');}
function projectGroups(id){return [...new Set(state.projects.filter(p=>p.id===id&&p.ad_group_name).map(p=>p.ad_group_name))];}
function projectSnapshotLimit(value,fallback){const n=Number(value);return Number.isSafeInteger(n)&&n>0?n:fallback;}
function projectGrantLimited(){return (state.projectRecords||[]).length>=(state.projectGrantLimit||2000);}
function projectGrantNotice(){return projectGrantLimited()?note('Grant snapshot limit reached ('+Number(state.projectGrantLimit||2000).toLocaleString()+' records across all projects). Counts include returned records only; older grants may be missing.',true):'';}

function projectTabs(items,selected,prefix,label){return `<div class="project-tabs" role="tablist" aria-label="${label}">${items.map(([key,title])=>`<button type="button" role="tab" id="${prefix}-tab-${key}" aria-controls="${prefix}-panel" aria-selected="${selected===key}" tabindex="${selected===key?'0':'-1'}" data-${prefix}-tab="${key}">${title}</button>`).join('')}</div>`;}
function projectLabel(a){return a.project_name||(a.project_id?'Project #'+a.project_id:'Workspace settings');}
function projectEvents(id){return (state.projectAudit||[]).filter(a=>!id||a.project_id===id).slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));}
function projectPager(total,page,attribute){const pages=Math.max(1,Math.ceil(total/PROJECT_PAGE_SIZE));return `<div class="project-pagination"><span role="status">${total?`${page*PROJECT_PAGE_SIZE+1}–${Math.min(total,(page+1)*PROJECT_PAGE_SIZE)} of ${total} events`:'0 events'} · up to ${state.projectAuditLimit||500} returned</span><div><button type="button" class="button small" ${page===0?'disabled':''} ${attribute}="${page-1}" aria-label="Previous events">Previous</button><button type="button" class="button small" ${page>=pages-1?'disabled':''} ${attribute}="${page+1}" aria-label="Next events">Next</button></div></div>`;}
function projectActivity(id,detail=false){if(state.projectAuditError)return note('Project activity unavailable: '+esc(state.projectAuditError)+'. Refresh to try again.',true);const events=projectEvents(id),key=detail?'projectHistoryPage':'projectActivityPage',page=Math.min(Math.max(0,state[key]||0),Math.max(0,Math.ceil(events.length/PROJECT_PAGE_SIZE)-1));state[key]=page;return `<div class="project-activity">`+table(detail?['When','Actor','Event','Evidence']:['When','Project','Actor','Event','Evidence'],events.slice(page*PROJECT_PAGE_SIZE,(page+1)*PROJECT_PAGE_SIZE).map(a=>[esc(new Date(a.created_at).toLocaleString()),...(!detail?[esc(projectLabel(a))]:[]),esc(a.actor||'Not recorded'),esc(human(a.action)),`<button type="button" class="app-link" data-project-audit="${Number(a.id)}" ${detail?'data-project-parent="'+Number(id)+'"':''}>View event</button>`]),'No project activity returned')+projectPager(events.length,page,detail?'data-project-history-page':'data-project-page')+'</div>';}
function projectRegisterRows(){const status=projectFilter(),q=(state.projectQuery||'').trim().toLowerCase(),all=scopedProjects(),projects=all.filter(p=>(status==='all'||p.status===status)&&(!q||[p.name,p.description,...projectGroups(p.id),...state.links.filter(l=>l.project_id===p.id).map(l=>l.app_name)].join(' ').toLowerCase().includes(q)));return `<p class="project-result-count" role="status">${projects.length} ${projects.length===1?'project':'projects'}${q?' matching your search':''}</p>`+(projects.length?'<ul class="project-list" aria-label="Projects">'+projects.map(p=>{const links=state.links.filter(l=>l.project_id===p.id),appCount=new Set(links.map(l=>Number(l.catalog_id))).size,grants=(state.projectRecords||[]).filter(g=>g.project_id===p.id),failed=grants.filter(g=>g.ad_action_on_add==='failed').length;return `<li><button type="button" class="project-row" data-project-record="${Number(p.id)}"><span class="project-identity"><span class="project-name">${esc(p.name)}</span>${p.description?`<span class="project-description">${esc(p.description)}</span>`:''}<span class="project-meta"><span class="project-state ${p.status==='active'?'is-active':''}">${esc(human(p.status))}</span><span>${appCount?`${appCount} linked ${appCount===1?'application':'applications'}`:'Unmapped'}</span><span>${state.projectAuditError?'Grant records unavailable':`${grants.length} ${projectGrantLimited()?'returned':'recorded'} ${grants.length===1?'grant':'grants'}`}</span>${!state.projectAuditError&&failed?`<span class="project-failure">${failed} AD add ${failed===1?'failure':'failures'}</span>`:''}</span></span><span class="project-chevron" aria-hidden="true">›</span></button></li>`;}).join('')+'</ul>':`<div class="empty"><strong>${q?'No matching projects':status==='active'?'No active projects':status==='closed'?'No closed projects':'No projects in this scope'}</strong><p>${q?'Try a different name, description, group or application.':'Choose another status filter to browse the register.'}</p></div>`);}
function projectRegister(){const projects=scopedProjects(),filter=projectFilter();return projectGrantNotice()+`<div class="project-toolbar"><div class="project-filters" role="group" aria-label="Project status">${[['active','Active'],['closed','Closed'],['all','All']].map(([key,label])=>`<button type="button" data-project-filter="${key}" aria-pressed="${filter===key}">${label}<span>${key==='all'?projects.length:projects.filter(p=>p.status===key).length}</span></button>`).join('')}</div><input id="project-query" type="search" aria-label="Search projects" placeholder="Search projects…" value="${esc(state.projectQuery||'')}"></div><div id="project-results">${projectRegisterRows()}</div>`;}
function userProjects(){if(!state.projectRead)return empty('User Projects unavailable',state.projectError||'Project records could not be loaded.');const view=state.projectView||'register';return `<section class="panel project-workspace"><div class="project-workspace-heading"><div><h2>Project register</h2><p>Explore project groups, application mappings and recorded access.</p></div></div>${projectTabs([['register','Projects'],['activity','Activity']],view,'project-view','User Projects views')}<div id="project-view-panel" role="tabpanel" tabindex="0" aria-labelledby="project-view-tab-${view}">${view==='activity'?projectActivity(projectScope()):projectRegister()}</div><div class="panel-bottom project-footnote">Recorded grants do not verify current access. Unmapped projects do not establish AI use.${projectScope()?' <a href="/ai-governance.html#projects">Show all User Projects ↗</a>':''}</div></section>`;}
function projectDetailBody(p,tab){const grants=(state.projectRecords||[]).filter(g=>g.project_id===p.id),links=state.links.filter(l=>l.project_id===p.id),groups=projectGroups(p.id);if(tab==='history')return projectActivity(p.id,true);if(tab==='access')return state.projectAuditError?note('Grant records unavailable: '+esc(state.projectAuditError)+'. Refresh to try again.',true):projectGrantNotice()+'<p class="project-detail-note">Recorded grants are historical evidence; current membership and entitlements require separate verification.</p>'+table(['User','Group','Recorded state','Grant / expiry','Actor'],grants.map(g=>[esc(g.user_display_name||g.user_identity)+`<small>${esc(g.user_identity)}</small>`,esc(g.ad_group_name),esc(human(g.status))+`<small>AD add: ${esc(g.ad_action_on_add||'Not recorded')} · remove: ${esc(g.ad_action_on_remove||'Not recorded')}</small>`,when(g.granted_at)+`<small>${g.expires_at?'Expires '+when(g.expires_at):'No expiry recorded'}</small>`,esc(g.granted_by)]),'No grants returned');return `<div class="project-overview">${projectGrantNotice()}<dl class="detail-summary"><div class="fact"><dt>Status</dt><dd>${esc(human(p.status))}</dd></div><div class="fact"><dt>${groups.length===1?'Existing group':'Existing groups'}</dt><dd>${groups.length?groups.map(esc).join('<br>'):'No group linked'}</dd></div><div class="fact"><dt>${projectGrantLimited()?'Returned grants':'Recorded grants'}</dt><dd>${state.projectAuditError?'Unavailable':grants.length}</dd></div></dl><h3>Business description</h3><p>${esc(p.description||'No business description recorded.')}</p><div class="project-mapping-heading"><h3>Linked applications</h3>${state.admin&&groups.length?`<button type="button" class="button small" data-link-project="${Number(p.id)}">Link application</button>`:''}</div>${links.length?'<ul class="project-mappings">'+links.map(l=>`<li><button type="button" class="app-link" data-app="${Number(l.catalog_id)}">${esc(l.app_name)}</button><p>${esc(l.ad_group_name)}${l.access_level?' · '+esc(l.access_level):''}</p></li>`).join('')+'</ul>':'<p class="muted">No application mapping recorded.</p>'}${state.admin&&!groups.length?'<p class="muted">An existing project group is required to link an application.</p>':''}<p class="project-detail-note">Application mappings describe recorded relationships. Linking does not change memberships or entitlements.</p></div>`;}
function projectRecord(n){const p=state.projects.find(p=>p.id===Number(n));if(!p)return;state.projectDetailId=p.id;state.projectHistoryPage=0;open(p.name,projectTabs([['overview','Overview'],['access','Recorded access'],['history','History']],'overview','project-detail','Project details')+`<div id="project-detail-panel" role="tabpanel" tabindex="0" aria-labelledby="project-detail-tab-overview">${projectDetailBody(p,'overview')}</div>`,null);$('editor').querySelector('.dialog-footer [data-close]').textContent='Done';}
function projectDetailTab(tab){const p=state.projects.find(p=>p.id===state.projectDetailId);if(!p)return;document.querySelectorAll('[data-project-detail-tab]').forEach(b=>{const selected=b.dataset.projectDetailTab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});$('project-detail-panel').setAttribute('aria-labelledby','project-detail-tab-'+tab);$('project-detail-panel').innerHTML=projectDetailBody(p,tab);}
function projectViewTab(tab){state.projectView=tab;document.querySelectorAll('[data-project-view-tab]').forEach(b=>{const selected=b.dataset.projectViewTab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});$('project-view-panel').setAttribute('aria-labelledby','project-view-tab-'+tab);$('project-view-panel').innerHTML=tab==='activity'?projectActivity(projectScope()):projectRegister();}
function projectTabKeys(e){const tab=e.target.closest('.project-tabs [role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=Array.from(tab.parentElement.querySelectorAll('[role=tab]')),index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();}

function accountBadge(a){const p=a.corporate_account||{};return badge(p.account_type||'unknown',['corporate','mixed'].includes(p.account_type)?'good':'')+`<small>${esc(p.sso_provider&&p.sso_provider!=='unknown'?ssoName(p.sso_provider):'SSO not verified')} · ${esc(human(p.sso_status||'not_verified'))}</small><button type="button" class="app-link" data-account="${Number(a.id)}">${state.admin?'Manage account / SSO':'View account / SSO'}</button>`;}
function ssoName(x){return {unknown:'Not yet verified',entra:'Entra',okta:'Okta',entra_and_okta:'Entra + Okta'}[x]||x;}
function accountForm(n){const a=state.apps.find(a=>a.id===Number(n));if(!a)return;const p=a.corporate_account||{};open(a.app_name+' · Corporate account & SSO',note('Label the organization’s account arrangement. Corporate accounts require Entra or Okta SSO. “Reported” records a confirmation; “Configured” requires an exact application reference and verification evidence. Individual users may still have different account arrangements.')+`<fieldset class="fields" style="border:0;padding:0;margin:0" ${state.admin?'':'disabled'}>${select('Organization account arrangement','account_type',[['unknown','Unknown / not reviewed'],['corporate','Corporate account'],['mixed','Corporate and personal accounts observed'],['personal_only','Personal accounts only (confirmed)']],p.account_type||'unknown')}${select('Corporate plan tier','plan_tier',['unknown','enterprise','business','team','other'].map(x=>[x,human(x)]),p.plan_tier||'unknown')}${field('Corporate workspace / organization','workspace_name',p.workspace_name)}${field('Contract / account owner','contract_owner',p.contract_owner)}${select('Account verification source','verification_method',['unknown','user_confirmation','corporate_admin','procurement','vendor_api'].map(x=>[x,human(x)]),p.verification_method||'unknown')}${field('Account verification date','verified_on',p.verified_on,'date')}${field('Corporate account evidence URL','evidence_url',p.evidence_url,'url',true)}${textarea('Corporate account confirmation / evidence note','verification_note',p.verification_note)}${select('SSO / identity platforms','sso_provider',['unknown','entra','okta','entra_and_okta'].map(x=>[x,ssoName(x)]),p.sso_provider||'unknown')}${select('SSO verification status','sso_status',[['not_verified','Not yet verified'],['reported','Reported / user confirmed'],['configured','Configuration verified'],['not_applicable','Not applicable (non-corporate only)']],p.sso_status||'not_verified')}${field('Exact Entra / Okta SSO application references','sso_reference',p.sso_reference,'text',true,false,'Record immutable application IDs or admin record references; names and bookmarks alone are insufficient.')}${field('SSO configuration evidence URL','sso_evidence_url',p.sso_evidence_url,'url',true)}${textarea('SSO confirmation / configuration note','sso_note',p.sso_note)}</fieldset>`,state.admin?b=>api('/accounts/'+a.id,{method:'PUT',body:JSON.stringify({...b,revision:a.corporate_revision||0})}):null,'Save account & SSO labels');}

function reportData(){return AIGovernanceOwnerPurpose.attach(AIGovernanceReports.build(state,state.reportFilter||{}));}
function assessmentPanels(r){const s=r.assessments,show=v=>v==null?'Unknown':String(v),groups=[...new Set(s.metrics.map(x=>x.group))];
 const selected=s.metrics.find(m=>m.id===state.assessmentFocus),details=selected?selected.details.filter(a=>a.result!=='Other recorded answer'):[];
 const drill=selected?panel(esc(selected.label)+' · affected applications',details.length+' applications with a signal or an unanswered / uncertain answer',table(['Application','Recorded answer','Reason','Assessment'],details.slice(0,50).map(a=>[esc(a.name),esc(a.value),esc(a.result),'<a href="/ai-governance.html?riskApp='+a.id+'#risk">Review assessment ↗</a>']))+(details.length>50?'<p class="gov-coverage-note">First 50 shown. Download the risk and controls CSV for all scoped records.</p>':''),'<button class="button" data-clear-assessment>Close breakdown</button>'):'';
 return '<section class="assessment-report section-space" aria-label="Risk and control report"><div class="panel-header"><div><h2>Risk indicators &amp; control gaps</h2><p>'+esc(s.note)+'</p><p>Assessment source read '+esc(s.read_at?new Date(s.read_at).toLocaleString():'Unavailable')+' · '+s.total+' scoped applications</p></div><button class="button" data-export="risk_controls" '+(!s.available||state.partial?'disabled':'')+'>Download risk &amp; controls CSV</button></div><div class="two-col">'+groups.map(group=>panel(esc(group),group==='Control gaps'?'Recorded follow-up answers; blank and uncertain answers remain separate':group==='Assigned risk tiers'?'Completed assessment tiers; separate from application approval':group==='Application lifecycle'?'Saved assessment status; separate from approval or observed usage':'Saved indicators prompt review; they do not assign risk',table(['Measure','Recorded count','Unanswered / uncertain','Details'],s.metrics.filter(m=>m.group===group).map(m=>[esc(m.label),show(m.count),show(m.unknown),'<button class="button small" data-report-assessment="'+m.id+'" '+(!s.available||!(m.count||m.unknown)?'disabled':'')+' aria-label="Review '+esc(m.label)+'">Review</button>'])))).join('')+'</div><div data-assessment-breakdown>'+drill+'</div><p class="gov-coverage-note">Intake submission is a self-reported assessment answer. No Access Portal queue records are pulled in. <a href="#risk">Open Risk Assessments ↗</a></p></section>';
}
function ownerPurposeMeasures(r){return [['Missing business owners',r.ownerPurpose.missing_owners,'Accountable team or person still needed'],['Missing business purposes',r.ownerPurpose.missing_purposes,'Concrete business workflows still needed'],['Missing both',r.counts.owner_purpose_missing_both,'Overlaps the missing-owner and purpose counts'],['Owner and purpose recorded',r.counts.owner_purpose_complete,'Metadata recorded; separate from approval']];}
function reportDisclosure(key,title,description,body){return '<details class="report-details" data-report-details="'+esc(key)+'" '+(state.reportDetails?.[key]?'open':'')+'><summary><strong>'+esc(title)+'</strong><span>'+esc(description)+'</span></summary><div class="report-details-body">'+body+'</div></details>';}
function reportScopeLabel(f){const labels=[];if(f.type)labels.push('AI type: '+human(f.type));if(f.category)labels.push('Category: '+f.category);if(f.account)labels.push('Account: '+human(f.account));if(f.sso)labels.push('SSO: '+ssoName(f.sso));return labels.join(' · ')||'All applications';}
function reportCoverageNotice(r){const limited=r.sources.filter(x=>/partial|unavailable|failed|denied|retained|unknown/i.test(String(x[1]))).length;return note((state.partial?'<strong>Some reads are incomplete; exports remain unavailable until refreshed.</strong> ':'')+(!r.identityRead?'Directory access evidence is unavailable to this account. ':'')+(state.identityAccess?.retained?'Directory evidence is retained from '+esc(whenTime(state.identityAccess.checked_at))+'. ':'')+(state.identityAccess?.status==='partial'?'Directory counts are partial lower bounds. ':'')+(r.assessments.available?'':'Assessment data is unavailable. ')+(limited?limited+' source checks have partial or unavailable coverage. ':'')+'Activity is a bounded sample; unknowns stay unknown. Zscaler is primary where matched, with supporting evidence and actual source dates retained. Expand Source coverage &amp; methods for details.',state.partial);}
function ownerPurposeSummaryPanel(r){const m=r.ownerPurpose;return '<div class="owner-purpose-report-summary">'+panel('Owner & business purpose review summary',`${m.inventory_count} applications in this report scope · current saved metadata`,'<p class="report-owner-note">Counts overlap. Recorded metadata is separate from confirmed answers; select a count to open its matching review list.</p>'+`<div class="metrics report-metrics">${ownerPurposeMeasures(r).map(([label,count,help],i)=>`<a class="metric owner-summary-link" href="${esc(AIGovernanceOwnerPurpose.reviewLink(['owner','purpose','both','complete'][i],r.filter))}" aria-label="${esc(label)}: ${count} applications. Open matching review list"><span>${esc(label)}</span><strong>${count}</strong><small>${esc(help)} · View list ↗</small></a>`).join('')}</div>`+(!m.identity_available?note('Directory evidence is unavailable to this account or has not been collected. Access-based priorities are unknown; available activity and catalog evidence are retained.',true):'')+reportDisclosure('owner-priorities','Owner and purpose review details',`${r.counts.owner_purpose_evidence_backed} evidence-backed gaps · ${m.rows.length} gaps overall`,`<div class="two-col"><section><h3>Review priorities</h3>${table(['Evidence behind priority','Applications'],m.tiers.map(x=>[esc(x.label),String(x.count)]))}<p>${r.counts.owner_purpose_evidence_backed} applications with access or usage evidence need follow-up; ${m.rows.length} need an owner or purpose overall. Each application appears in one priority group.</p></section><section><h3>Next applications to review</h3>${table(['Application / source','Owner / missing fields','Review'],m.rows.slice(0,6).map(x=>[appButton({id:x.id,app_name:x.name})+'<small>'+esc(x.primary_source+' / '+x.preferred_label)+'</small><small>Supporting: '+esc(x.other_sources||'No additional source recorded')+'</small>',esc(x.owner||'Not recorded')+'<small>'+esc(x.missing.join(' · '))+'</small>','<a href="'+esc(x.url)+'">Review ↗</a>']),'No owner or purpose gaps in this report scope')}<p>First ${Math.min(6,m.rows.length)} of ${m.rows.length} records. Export all matching gaps below; use Governance Queue for search and evidence details.</p></section></div>`+note('Zscaler remains primary where positively matched. Other sources and their original collection dates remain attributed. Entra/Okta counts are separate; missing evidence does not establish non-use.')),`<button class="button" data-export="owner_purpose" ${state.partial?'disabled':''}>Download owner / purpose CSV</button>`)+'</div>';}
function ownerPurposeBrief(r,renderRows){const m=r.ownerPurpose;return '<h2>Owner &amp; business purpose review summary</h2><p>'+m.inventory_count+' applications in the current report scope. Priority is follow-up order, separate from risk, approval or AI-feature use. Missing-owner and missing-purpose measures overlap; each application is in one priority group.</p>'+renderRows(['Measure','Applications','Meaning'],ownerPurposeMeasures(r))+renderRows(['Evidence behind priority','Applications'],m.tiers.map(x=>[x.label,x.count]))+'<p>'+r.counts.owner_purpose_evidence_backed+' evidence-backed applications need follow-up; '+m.rows.length+' need an owner or purpose overall. Current metadata follows application filters, not request/audit dates. '+(m.identity_available?'':'Directory evidence is unavailable; access-based priority is unknown. ')+'</p>'+renderRows(['Application','Business owner','Missing fields','Primary source / label','Supporting evidence'],m.rows.slice(0,6).map(x=>[x.name,x.owner||'Not recorded',x.missing.join('; '),x.primary_source+' / '+x.preferred_label,x.other_sources||'No additional source recorded']))+'<p>First '+Math.min(6,m.rows.length)+' of '+m.rows.length+' follow-up records shown. The owner/purpose CSV includes all gaps in this report scope, with source timestamps and collection run IDs. Zscaler labels stay primary where matched and other evidence remains attributed.</p>';}
function reports(){const r=reportData(),f=r.filter,unknown=v=>v==null?'Unknown':v,metrics=[['Catalog applications',r.counts.applications,'Candidates and reviewed entries'],['Approved Applications',r.counts.approved,'Recorded governance decisions'],['Embedded AI',r.counts.embedded,'Explicit embedded / both classification'],['Needs review',r.counts.review,'Missing fields, decisions or review dates']];return `<div class="report-controls panel"><div class="panel-header"><div><h2>Legal & InfoSec report scope</h2><p>Inventory read ${esc(when(r.read_at))} · Generated ${esc(new Date(r.generated_at).toLocaleString())}</p></div><div class="report-primary-downloads"><button class="button" data-legal-brief ${state.partial?'disabled':''}>Download Legal brief</button><button class="button" data-export="summary" ${state.partial?'disabled':''}>Executive measures CSV</button><button class="button" data-export="inventory" ${state.partial?'disabled':''}>Inventory CSV</button></div></div><p class="report-scope">Application scope: ${esc(reportScopeLabel(f))}. Request/audit dates: ${esc(f.from||'Any')} to ${esc(f.to||'Any')} (submission and audit events only).</p>${reportDisclosure('filters','Report filters',reportScopeLabel(f),`<div class="fields report-filters">${select('AI type','report-type',[['','All types'],...['standalone','embedded','both','unclassified'].map(x=>[x,human(x)])],f.type||'')}${select('Primary category','report-category',[['','All categories'],...categories.map(x=>[x,x])],f.category||'')}${select('Account arrangement','report-account',[['','All arrangements'],...['corporate','mixed','personal_only','unknown'].map(x=>[x,human(x)])],f.account||'')}${select('SSO provider','report-sso',[['','All identity platforms'],...['entra','okta','entra_and_okta','unknown'].map(x=>[x,ssoName(x)])],f.sso||'')}${field('Request / audit start date','report-from',f.from||'','date')}${field('Request / audit end date','report-to',f.to||'','date')}</div>`)}</div><div class="metrics report-metrics">${metrics.map(m=>`<div class="metric"><span>${m[0]}</span><strong>${m[1]}</strong><small>${m[2]}</small></div>`).join('')}</div>${ownerPurposeSummaryPanel(r)}${reportCoverageNotice(r)}${reportDisclosure('confirmations','Owner and purpose confirmations','Separate reviewed answers from recorded inventory', '<div id="purpose-report-view"></div>')}${reportDisclosure('risk-controls','Risk and control details',r.assessments.available?`${r.assessments.total} scoped applications`:'Assessment data unavailable',assessmentPanels(r))}${reportDisclosure('directory','Directory access evidence',r.identityRead?`${r.identityRows.length} application/provider groups · providers kept separate`:'Permission required or evidence unavailable',identityAccessPanel(r))}${reportDisclosure('breakdowns','Access, intake and classification','Detailed coverage counts and category breakdown',`<div class="two-col">${panel('Access & intake coverage','Recorded evidence; no inferred vendor seats',table(['Measure','Result'],[['Shadow IT application rows in scope',String(unknown(r.counts.shadow_it_applications))],['Shadow IT applications matched to inventory',String(unknown(r.counts.shadow_it_catalog_applications))],['Rapid7 applications matched to inventory',String(unknown(r.counts.rapid7_catalog_applications))],['Rapid7 observed sample for those applications',String(unknown(r.counts.rapid7_catalog_observations))],['Corporate accounts',String(r.counts.corporate_accounts)],['Corporate SSO configuration verified',String(r.counts.corporate_sso_verified)],['Corporate SSO needs verification',String(r.counts.corporate_sso_needs_verification)],['Account arrangement unknown',String(r.counts.account_type_unknown)],['Active manual access records',String(r.counts.manual_access_rows)],['Active project grant records',String(unknown(r.counts.project_access_rows))],['Original grant date unknown',String(unknown(r.counts.unknown_original_grant_dates))],['Failed project grants',String(unknown(r.counts.failed_project_grants))],['Projects mapped to AI applications',`${unknown(r.counts.linked_projects)} mapped · ${unknown(r.counts.active_projects)} active projects overall`],['Open requests in submission-date scope',String(r.counts.open_requests)]]))}${panel('Classification breakdown','Current inventory in the selected scope',table(['Category','Applications','Approved'],r.categories.map(x=>[esc(x.label),String(x.total),String(x.approved)]),'No records in this scope'))}</div>`)}<div class="section-space"></div>${reportDisclosure('queue','Governance Queue priorities',`${r.review.length} applications with recorded gaps or review dates`,panel('Governance Queue priorities','Fields and evidence needed for a useful governance register',table(['Application','Owner','Missing / due'],r.review.slice(0,12).map(a=>[appButton(a),esc(a.owner||'Unassigned'),esc(a.gaps.join(' · '))]),'No review gaps found')+(r.review.length>12?'<div class="panel-bottom">Showing 12 of '+r.review.length+' records; export the complete returned Governance Queue below.</div>':'')))}<div class="section-space"></div>${reportDisclosure('exports','Additional CSV exports','Access, SSO, activity, classification and audit evidence',`<div class="two-col report-downloads">${[['owner_purpose','Owner & business purpose review','All owner/purpose gaps in the current report scope, prioritized by saved access and usage evidence, with source labels and collection dates.'],['identity_access','Directory access evidence','Distinct accounts per application and provider, assignments, group membership, licenses, inactive instances and collection dates.'],['summary','Executive measures','Current counts with unknowns preserved.'],['inventory','AI Inventory','Vendor, primary category, tags, capability, owner, purpose, approval, review date and evidence.'],['access','Manual & project access records','User, access level, purpose, original grant date or unknown, project event date, expiry and source.'],['corporate','Corporate accounts & SSO','Account ownership, plan tier, workspace, contract owner, verification source, SSO providers and configuration gaps.'],['requests','Intake Requests','Intake, business purpose, status, reviewers and decision timestamps.'],['review','Governance Queue','Missing metadata, unreviewed decisions and overdue dates.'],['categories','Category & tag summary','Application counts by primary category and overlapping tags, including custom classifications.'],['evidence','Source evidence register','Vendor capability claims and enterprise app presence, with dates and identifiers.'],['sources','Source coverage','Read status, partial coverage, check time and cache dates.'],['discovery','Discovery candidate queue','Available vendor definitions, enterprise name matches and reference candidates; evidence type and limits retained.'],['shadow_it','Shadow IT application usage','Application aggregates, users, transactions, traffic, vendor risk and sanction labels, with their report window and collection date.'],['rapid7','Observed activity & origins','Rapid7 observations, accounts, original log source, event IDs, outcomes and source timestamps; separate from access grants.'],['changes','Recorded change history','Actors and actions in the selected audit-event date range; limited to returned history.']].filter(([key])=>!['owner_purpose','summary','inventory'].includes(key)).map(([key,title,desc])=>`<section class="panel report-card"><h2>${title}</h2><p>${desc}</p><button class="button" data-export="${key}" ${state.partial||key==='identity_access'&&!r.identityRead||key==='access'&&!state.projectRead||key==='rapid7'&&!state.rapid7ObservationRead||key==='shadow_it'&&!r.shadowRead?'disabled':''}>Download CSV</button></section>`).join('')}</div>`)}<div class="section-space"></div>${reportDisclosure('methods','Source coverage & methods',`${r.sources.length} source checks · saved dates and detailed limitations`,`${panel('Source freshness & limitations','Successful reads are not proof of complete discovery',table(['Source','Status','Last source check','Cache evidence'],r.sources.map(x=>[esc(x[0]),esc(x[1]),esc(when(x[2])),esc(x[4]?when(x[4]):x[5])])))}${note('Scheduled Legal email, SharePoint synchronization and Claude / Copilot extraction are not connected. These reports use the records currently visible to your account. <a href="#sources">Review discovery sources and classification options ↗</a>')}${r.warnings.map(x=>note(esc(x),true)).join('')}`)}`;}
function saveBlob(body,type,name){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function download(key){try{const r=key==='identity_access'&&state.view!=='reports'?AIGovernanceReports.build(state,{}):reportData();saveBlob(key==='owner_purpose'?AIGovernanceOwnerPurpose.csv(r.ownerPurpose,{tier:''}):AIGovernanceReports.csv(key,r),'text/csv;charset=utf-8','ai-governance-'+key+'-'+new Date().toLocaleDateString('en-CA')+'.csv');}catch(e){toast(e.message);}}
function legalBrief(){if(state.partial)return toast('Refresh incomplete sources before exporting.');const r=reportData(),renderRows=(heads,rows)=>`<table><thead><tr>${heads.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(x=>'<tr>'+x.map(c=>'<td>'+esc(c==null?'Unknown':c)+'</td>').join('')+'</tr>').join('')}</tbody></table>`,summary=AIGovernanceReports.rows('summary',r);const shadowSummary=r.shadowRead?'<h2>Shadow IT application usage</h2><p>Application aggregates for the seven-day report collected '+esc(r.shadowCheckedAt)+(r.shadowRetained?' (retained after an unavailable read)':'')+'. Vendor report period: '+esc(r.shadowPeriod||'Not supplied')+'. Retrieval time is separate from coverage. User counts overlap across applications. Traffic does not establish AI-feature use, access or approval.</p>'+renderRows(['Application','Reported users','Transactions','Data consumed (reported)','Vendor risk','Vendor sanction'],r.shadowRows.slice(0,25).map(x=>[x.name,x.users,x.transactions,x.data_consumed,x.risk,x.sanction]))+'<p>First 25 of '+r.shadowRows.length+' application rows in scope shown. Use the Shadow IT CSV for every returned row.</p>':'';const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI governance · Legal & InfoSec brief</title><style>body{font:14px/1.5 system-ui,sans-serif;color:#14243b;max-width:1100px;margin:40px auto;padding:0 25px}h1{font-size:30px}h2{margin-top:32px;font-size:20px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:9px;border-bottom:1px solid #dce3ec;vertical-align:top;overflow-wrap:anywhere}th{background:#edf2f8}li{margin:7px 0}.meta{color:#52637b}@media print{body{margin:0;padding:0}h2{break-after:avoid}tr{break-inside:avoid}}</style></head><body><p class="meta">CorpIT · Legal & Information Security · Governance inventory</p><h1>AI governance report</h1><p>Generated '+esc(r.generated_at)+' · Inventory read '+esc(r.read_at||'Unknown')+'</p><p>Scope: '+esc(r.filter.type||'All AI types')+' · '+esc(r.filter.category||'All categories')+' · Account '+esc(r.filter.account||'All')+' · SSO '+esc(r.filter.sso||'All')+' · Request/audit submissions '+esc(r.filter.from||'Any')+' to '+esc(r.filter.to||'Any')+'</p><h2>Coverage and interpretation</h2><ul>'+r.warnings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h2>Executive measures</h2>'+renderRows(summary.columns,summary.data)+ownerPurposeBrief(r,renderRows)+'<h2>Risk indicators &amp; control gaps</h2><p>'+esc(r.assessments.note)+' Assessment source read '+esc(r.assessments.read_at||'Unavailable')+'</p>'+renderRows(['Group','Measure','Recorded count','Unanswered / uncertain'],r.assessments.metrics.map(m=>[m.group,m.label,m.count,m.unknown]))+shadowSummary+'<h2>Corporate accounts & SSO</h2>'+renderRows(['Application','Discovery source','Account','Plan tier','Identity platforms','SSO verification'],r.apps.filter(a=>['corporate','mixed'].includes((a.corporate_account||{}).account_type)).map(a=>[a.app_name,a.provenance.primary_source,a.corporate_account.account_type,a.corporate_account.plan_tier,ssoName(a.corporate_account.sso_provider),a.corporate_account.sso_status]))+'<h2>Classification</h2>'+renderRows(['Category','Applications','Approved','Embedded AI','Needs review'],r.categories.map(x=>[x.label,x.total,x.approved,x.embedded,x.incomplete]))+'<h2>Classification tags</h2>'+renderRows(['Tag','Applications','Approved'],r.tags.map(x=>[x.label,x.total,x.approved]))+'<h2>Governance Queue</h2>'+renderRows(['Application','Owner','Missing / overdue'],r.review.slice(0,25).map(a=>[a.app_name,a.owner||'Unassigned',a.gaps.join('; ')]))+'<p>First 25 of '+r.review.length+' review records shown. Use the Governance Queue CSV for all returned records.</p><h2>Discovery source coverage</h2>'+renderRows(['Source','Read status','Checked at','Returned','Oldest cache','Limitations'],r.sources)+'<p class="meta">This brief contains recorded governance facts and completeness gaps. It does not establish complete enterprise discovery, current vendor entitlements, or effective policy enforcement. Use browser Print / Save as PDF for a PDF copy.</p></body></html>';saveBlob(html,'text/html;charset=utf-8','ai-governance-legal-brief-'+new Date().toLocaleDateString('en-CA')+'.html');}
function rapid7Rows(items){return table(['Application / site','Evidence origin','Observed events','Source timestamps','Inventory'],items.slice(0,20).map(x=>[esc(x.name)+`<small>${esc(x.zscaler_label?'Preferred Zscaler label: '+x.zscaler_label:'Zscaler label not established in checked data')}</small>`,esc('Rapid7 → '+(x.origins||[]).join(', '))+`<small>${esc((x.logsets||[]).join(' · '))}</small>`,String(x.event_count)+`<small>${x.blocked_count} blocked / failed observations</small>`,esc(whenTime(x.first_observed))+`<small>to ${esc(whenTime(x.last_observed))}</small>`,x.catalog_id?`<button class="app-link" data-app="${Number(x.catalog_id)}">Review application</button>`:state.admin?`<button class="button small" data-attach-source="rapid7" data-source-code="${esc(x.code)}">Import candidate</button>`:'Review candidate']),'No matching AI application evidence in this bounded source check')+(items.length>20?'<div class="panel-bottom">Showing the first 20 of '+items.length+' matches. Filter to find the other candidates.</div>':'');}
function whenTime(v){return v?new Date(v).toLocaleString():'Not recorded';}
function rapid7WebCoverage(r){
 const q=r.query_scope?.web_discovery;if(!q)return '';const source=(r.sources||[]).find(x=>x.name==='Web Proxy Activity');
 return note(esc(q.policy))+'<details class="rapid7-detail"><summary>Web discovery query diagnostics</summary>'+table(['Discovery query','Raw records returned','New observations','Duration','Outcome'],(source?.discovery_checks||[]).map(x=>[esc(x.name),String(x.returned),String(x.accepted),(Number(x.duration_ms)/1000).toFixed(1)+' s',esc(x.reason)+(x.partial?' · Partial coverage':'')]),'No discovery diagnostics saved')+'</details>';
}
function rapid7CloudCoverage(r){
 const q=r.query_scope?.cloud_discovery;if(!q)return '';const source=(r.sources||[]).find(x=>x.name==='Cloud Service Activity');
 return note('Cloud Service discovery samples recognized Bedrock service fields first (up to '+Number(q.nativeNormalized)+' observations), then runs broad discovery. '+(q.recoveryMs?'Smaller broad pages reserve '+Number(q.recoveryMs/1000)+' seconds for native-service recovery after incomplete broad searches. Recovery fills only unused sample slots; broader coverage remains incomplete. ':'')+'Searches stop when the normalized family sample fills. Other cloud services, unqueried batches and incomplete searches remain unknown.')+'<details class="rapid7-detail"><summary>Cloud discovery query diagnostics</summary>'+table(['Discovery query','Raw records returned','New observations','Duration','Outcome'],(source?.discovery_checks||[]).map(x=>[esc(x.name),String(x.returned),String(x.accepted),(Number(x.duration_ms)/1000).toFixed(1)+' s',esc(x.reason)+(x.partial?' · Partial coverage':'')]),'No discovery diagnostics saved')+'</details>';
}
function rapid7Coverage(r){const q=r.query_scope;if(!q||!r.application_checks)return '';const threshold=Number(q.focusMinObservations||0),policy=threshold?'Apps with fewer than '+threshold+' broad observations remain eligible for focused checks. Up to '+Number(q.focusApps)+' apps are selected, prioritizing small positive samples before absent apps; '+Number(q.focus_omitted||0)+' other apps below the threshold were not selected in this run. Focused checks retain up to '+Number(q.focusNormalizedPerApp)+' additional deduplicated observations per selected app.':'Focused checks retain up to '+Number(q.focusNormalizedPerApp)+' observations per selected app and use application names, aliases and configured domains for up to '+Number(q.focusApps)+' unrepresented inventory apps; '+Number(q.focus_omitted||0)+' other unrepresented apps were not selected in this run.';return rapid7WebCoverage(r)+rapid7CloudCoverage(r)+note('Collection coverage: discovery searches up to '+Number(q.broadRawPerFamily)+' raw events per log family and retains up to '+Number(q.broadNormalizedPerFamily)+' normalized discovery observations per family. '+policy+' Unchecked or incomplete results remain unknown. The normalized sample is capped at '+Number(q.maxObservations)+' observations.'+(q.focused_fields?' Focused searches use exact application/alias fields and configured domain fields, newest first. Email and message mentions are excluded.':'')+(q.focused_vocabulary?' Shared aliases and domains that link to another inventory entry are excluded from each focused filter.':'')+(q.focused_cloud_retry?' Incomplete focused Cloud searches can retry owned service names and the most recent hour of application/domain fields within the original twenty-second budget. Recent-hour and service subsets never complete an unfinished full-window search.':'')+(q.focused_sso_retry?' Incomplete focused SSO searches may retry exact owned application names in the normalized service field within the same 20-second SSO budget. An empty native-service result does not complete an unfinished broader search.':'')+(q.focused_web_retry?' Incomplete focused Web searches can retry exact observed hostnames that still belong to the selected entry, then native labels, within the same 20-second budget. Focused queries use smaller pages and stop at the remaining unique-record cap; completed main queries are not retried.':''))+(q.focused_full_window_retry?note(esc(q.focused_full_window_retry.policy)):'')+'<details class="rapid7-detail"><summary>Focused inventory coverage checks ('+r.application_checks.length+')</summary>'+table(['Application','Observed sample','Focused queries completed','Coverage','Query outcomes'],r.application_checks.map(x=>[esc(x.name),String(x.observation_count)+(Number.isFinite(x.broad_observation_count)?'<br><small>Broad '+x.broad_observation_count+' · Focused +'+Number(x.focused_observation_count||0)+'</small>':''),String(x.queries_completed)+' / '+String(x.queries_planned),esc(x.status)+(x.full_window_recovered&&!x.partial?'<br><small>Original full-window predicates completed after retry; earlier attempts remain audited.</small>':'')+(x.partial?' · Partial coverage':'')+(x.selection_reason?'<br><small>'+esc(x.selection_reason)+'</small>':'')+(x.broad_linked_after_selection?'<br><small>Selected with '+Number(x.selection_broad_observation_count)+' broad observations; '+Number(x.broad_linked_after_selection)+' broad links resolved during reconciliation</small>':'')+(x.excluded_term_count?'<br><small>'+Number(x.excluded_term_count)+' terms for other inventory entries excluded</small>':''),(x.families||[]).map(f=>esc(f.name)+': '+((f.outcomes||[]).map(o=>(o.strategy?esc(o.strategy)+' · ':'')+(o.query_window?'Window '+esc(whenTime(o.query_window.from))+' to '+esc(whenTime(o.query_window.to))+' · ':'')+esc(o.reason)+(o.returned?' ('+Number(o.returned)+' returned, '+Number(o.accepted)+' added)':'')).join('; ')||esc(f.note||'No query diagnostics saved'))).join('<br>')]),'No focused checks were needed')+'</details>';}
function rapid7Panel(){const r=state.rapid7||{},job=r.job||{},running=job.status==='running';return panel('Rapid7 activity evidence',r.checked_at?'Collected '+whenTime(r.checked_at)+' · Query window '+whenTime(r.window.from)+' to '+whenTime(r.window.to):'No activity collection recorded',note('Collector: Rapid7 InsightIDR. Original sources stay attached to each observation. Zscaler labels take precedence; forwarded Zscaler events are not independent confirmation. Web requests, DNS lookups and authentication events do not establish AI-feature use, a licensed seat, or an access grant.')+(r.error?note(esc(r.error),true):'')+(job.status?'<div id="rapid7-job-status">'+note('Latest collection: '+esc(job.status)+' · '+esc(job.phase||'')+(job.error?' · '+esc(job.error):''),job.status==='failed')+'</div>':'')+table(['Log family','Query status','Matching evidence','Returned events','Coverage'],(r.sources||[]).map(x=>[esc(x.name),esc(x.status===200?(x.partial?'Partial read':'Read available'):x.status?'HTTP '+x.status:'Unavailable'),String(x.status===200?x.count||0:'Unknown'),String(x.queried_events==null?'Unknown':x.queried_events),esc(x.note)]),'Run a source check to read the permitted log families')+rapid7Coverage(r)+`<div class="toolbar"><input id="rapid7-filter" aria-label="Filter Rapid7 applications" placeholder="Filter applications, domains or original sources…" value="${esc(state.rapid7q||'')}"></div><div id="rapid7-results">${rapid7Rows((r.candidates||[]).filter(x=>[x.name,...(x.origins||[]),...(x.domains||[])].join(' ').toLowerCase().includes((state.rapid7q||'').toLowerCase())))}</div><div class="panel-bottom">${Number(r.observation_count||0)} normalized observations · counts are bounded Rapid7 samples, not enterprise totals. Full URLs, prompts, raw bodies and IP addresses are not retained.</div>`+`<details class="rapid7-detail"><summary>Observed accounts and source references</summary><p class="muted">${state.rapid7ObservationRead?'Requires Identity Diagnostics and Zscaler read access. Observations are separate from recorded entitlements.':esc(state.rapid7ObservationError||'Activity details require additional source permissions.')}</p>${state.rapid7ObservationRead?`<div class="toolbar"><input id="rapid7-account-filter" aria-label="Filter Rapid7 observations" placeholder="Application, account, origin or log family"></div><div id="rapid7-observation-results">${rapid7ObservationRows(state.rapid7Observations||[])}</div><button class="button" data-export="rapid7">Download activity CSV</button>`:''}</details>`,state.admin?`<div class="rapid7-actions"><select id="rapid7-hours" aria-label="Rapid7 query window" ${running?'disabled':''}><option value="24">Last 24 hours</option><option value="168">Last 7 days</option></select><button class="button" data-check-rapid7 ${running?'disabled':''}>${running?'Collecting…':'Collect Rapid7 evidence'}</button></div>`:'');}
function rapid7ObservationRows(items){return table(['Application / account','Collector → original source','Evidence kind / outcome','Source event time','Source reference'],items.slice(0,50).map(x=>[esc(x.app_name)+`<small>${esc(x.user_identity||'Account not reported')}</small>`,esc('Rapid7 → '+x.original_source)+`<small>${esc(x.log_name||'Log name not reported')}</small>`,esc(human(x.evidence_kind))+`<small>${esc(x.result||'Outcome not reported')}</small>`,esc(whenTime(x.occurred_at))+`<small>${esc(x.event_time_basis)}</small>`,esc(x.logset_name)+`<small>Event: ${esc(x.source_event_id||x.fingerprint)}</small>`]),'No permitted matching activity records')+(items.length>50?'<div class="panel-bottom">First 50 of '+items.length+' matches shown. Filter or export the returned records.</div>':'');}
function rapid7AppEvidence(a){const rows=a.rapid7_evidence||[];if(!rows.length)return '';return `<div class="section-space"><h3>Rapid7 collected activity</h3>${note('Observed activity only. Preferred discovery label remains Zscaler where matched. These records do not change account ownership, access, enablement or approval.')}${table(['Collector → original source','Evidence window / event times','Observed sample','Source references'],rows.map(x=>[esc('Rapid7 → '+(x.origins||[]).join(', ')),esc(whenTime(x.first_observed))+'<small>to '+esc(whenTime(x.last_observed))+'</small><small>Collected '+esc(whenTime(x.checked_at))+'</small>',String(x.event_count)+' event(s)<small>'+Number(x.blocked_count)+' blocked / failed</small>',(x.source_refs||[]).map(r=>'<small>'+esc(r.logset_name)+' · '+esc(r.log_name||r.log_id||'Log name unknown')+' · '+r.count+' event(s)</small>').join('')+'<small>Run '+esc(x.run_id)+'</small>']))}</div>`;}
async function checkRapid7(button){button.disabled=true;try{const hours=Number($('rapid7-hours').value),start=await api('/rapid7-refresh',{method:'POST',body:JSON.stringify({hours})});state.rapid7={...state.rapid7,job:start.job};if(state.view==='sources')render();for(let i=0;i<240;i++){await new Promise(resolve=>setTimeout(resolve,1500));const next=await api('/rapid7-evidence');state.rapid7=next;if(!next.job||next.job.id!==start.job.id)throw new Error('Collection was interrupted. Refresh source status before trying again.');if(next.job.status!=='running'){await load();toast(next.job.status==='completed'?'Rapid7 evidence collected.':next.job.error||'Collection failed; previous evidence retained.');return;}if(state.view==='sources'){const status=$('rapid7-job-status');if(status&&status.firstElementChild)status.firstElementChild.textContent='Latest collection: '+next.job.status+' · '+next.job.phase;}}await load();toast(state.rapid7?.job?.status==='running'?'Collection is still running. Refresh the page for its result.':state.rapid7?.job?.status==='completed'?'Rapid7 evidence collected.':state.rapid7?.job?.error||'Collection finished. Review source status.');}catch(e){toast(e.message);await load();}}

function sourceEvidence(a){if(!a.id)return '';const preferred=AIGovernanceReports.provenance(a,state);const rows=(state.evidence||[]).filter(x=>Number(x.catalog_id)===Number(a.id));return rapid7AppEvidence(a)+ `<div class="section-space"><h3>Collected source evidence</h3>${note('Preferred discovery source: '+esc(preferred.primary_source)+'. Label: '+esc(preferred.preferred_label)+(preferred.source_category?' · '+esc(preferred.source_category):'')+'. Basis: '+esc(preferred.source_basis)+'. Source record: '+esc(preferred.source_record_id||'Not recorded')+'. Other collected sources: '+esc(preferred.other_sources||'None recorded')+'. '+esc(preferred.zscaler_match)+'.')} ${rows.length?table(['Kind / source','Capability / suggestion','Observed','Evidence'],rows.map(x=>[esc(human(x.evidence_kind))+'<small>'+esc(x.source_key)+'</small>',esc(x.capability_name||'Not specified')+'<small>Suggested category: '+esc(x.suggested_category||'No suggestion')+'</small>',esc(when(x.observed_at)),evidence(x.source_url)])):'<p class="muted">No manually attached source evidence. <a href="#sources">Review sources ↗</a></p>'}<p class="muted">Capability suggestions do not establish feature enablement, access or approval.</p></div>`;}
function sourceAction(x,source){const attached=(state.evidence||[]).find(e=>e.source_key===(source==='enterprise'?'entra':source==='rapid7'?'rapid7':'vendor')&&e.source_record_id===x.code);if(attached)return `<button class="app-link" data-app="${Number(attached.catalog_id)}">Evidence attached · review record</button>`;return state.admin?`<button class="button small" data-attach-source="${source}" data-source-code="${esc(x.code)}">${x.catalog_id?'Attach evidence':'Import candidate'}</button>`:x.catalog_id?'Inventory record #'+Number(x.catalog_id):'Unreviewed candidate';}
function sourceRows(rows,source){const limit=source==='enterprise'?20:100;return table(['Application / candidate','Evidence','Classification suggestion','Inventory action'],rows.slice(0,limit).map(x=>[esc(x.name)+`<small>${esc(x.vendor||'Vendor unknown')}</small>`,esc(human(x.evidence_kind))+`<small>${esc(x.match_basis||x.note||'')} ${x.observed_at?'Source observation '+when(x.observed_at):'Reference reviewed '+esc(x.verified_at||'')}</small>${evidence(x.url)}`,esc(x.suggested_category||'Needs classification')+`<small>${esc(x.capability_name||'AI capability requires review')}</small>`,sourceAction(x,source)]),'No candidates in this checked source')+(rows.length>limit?'<div class="panel-bottom">Showing '+limit+' of '+rows.length+' matches. Use the candidate filter to find other records. The checked source is not exhaustive.</div>':'');}
function refreshSchedule(){const r=state.refreshStatus||{},names={zscaler:'Zscaler',entra:'Microsoft Entra',rapid7:'Rapid7'},rows=r.sources||[];return panel('Automatic source refresh','Hourly sources refresh together at the top of each hour (:00). Zscaler labels stay primary; refreshes run even when this page is closed.',(r.error?note(esc(r.error),true):note(r.worker&&r.worker.healthy?'Refresh worker is online · This page checks for saved updates every 5 minutes.':'Refresh worker heartbeat is overdue or unavailable. Last saved evidence remains visible.',!(r.worker&&r.worker.healthy)))+`<div class="refresh-grid">${rows.map(x=>{const stale=!x.last_success_at||Date.now()-new Date(x.last_success_at).getTime()>(Number(x.interval_minutes)*2+5)*60000;return `<article class="refresh-card"><div class="refresh-card-title"><h3>${names[x.source_key]||esc(x.source_key)}</h3>${badge(!x.enabled?'Paused':x.last_status==='failed'?'Refresh failed':x.last_status==='running'?'Refreshing':stale?'Overdue':x.last_status==='partial'?'Current · partial coverage':'Current',!stale&&x.last_status!=='failed'?'good':'')}</div><dl><dt>Schedule</dt><dd>${x.enabled?(x.interval_minutes===60?'Hourly · at :00':'Every '+Number(x.interval_minutes/60)+' hours · aligned to the clock'):'Paused'}</dd><dt>Last successful collection</dt><dd>${esc(whenTime(x.last_success_at))}</dd><dt>Next scheduled check</dt><dd>${x.enabled?esc(whenTime(x.next_run_at)):'Paused'}</dd></dl>${x.last_error?note(esc(x.last_error),true):''}${state.admin?`<button class="button small" data-configure-refresh="${esc(x.source_key)}">Configure ${names[x.source_key]||esc(x.source_key)}</button>`:''}</article>`;}).join('')}</div>`+note('Entra reads current enterprise apps from Microsoft Graph. Rapid7 uses a rolling 24-hour window; sample limits remain visible. New candidates still require review.'))+'<div class="section-space"></div>';}
function refreshScheduleForm(key){const x=(state.refreshStatus?.sources||[]).find(x=>x.source_key===key);if(!x)return;const intervals=[60,120,360,720,1440];if(!intervals.includes(x.interval_minutes))intervals.push(x.interval_minutes);open('Automatic refresh · '+({zscaler:'Zscaler',entra:'Microsoft Entra',rapid7:'Rapid7'}[key]||key),note('Refresh evidence using the existing connection. Pausing stops future scheduled runs and retains saved evidence. Governance decisions and user access remain separate.')+`<label class="full"><span><input name="enabled" type="checkbox" ${x.enabled?'checked':''}> Automatic refresh enabled</span></label>`+select('Refresh interval','interval_minutes',intervals.sort((a,b)=>a-b).map(n=>[n,n===60?'Hourly · at :00':'Every '+n/60+' hours']),x.interval_minutes),b=>api('/refresh-schedule/'+key,{method:'PUT',body:JSON.stringify({enabled:b.enabled==='on',interval_minutes:Number(b.interval_minutes)})}),'Save refresh schedule');}

function sourceRefreshState(x){const stale=!x.last_success_at||Date.now()-new Date(x.last_success_at).getTime()>(Number(x.interval_minutes)*2+5)*60000;return {label:!x.enabled?'Paused':x.last_status==='failed'?'Refresh failed':x.last_status==='running'?'Refreshing':stale?'Overdue':x.last_status==='partial'?'Current · partial coverage':'Current',tone:!x.enabled||stale||['failed','partial'].includes(x.last_status)?'warn':'good'};}
function sourceStatusPanel(){const r=state.refreshStatus||{},names={zscaler:'Zscaler',entra:'Microsoft Entra',rapid7:'Rapid7'};return panel('Source status','Saved refresh state · collections continue when this page is closed',(r.error?note(esc(r.error),true):note(r.worker?.healthy?'Refresh worker is online.':'Refresh worker heartbeat is overdue or unavailable. Last saved evidence remains visible.',!r.worker?.healthy))+table(['Source / schedule','Refresh status','Last successful collection','Next scheduled check'],(r.sources||[]).map(x=>{const status=sourceRefreshState(x);return [esc(names[x.source_key]||x.source_key)+'<small>'+(x.enabled?(x.interval_minutes===60?'Hourly · at :00':'Every '+Number(x.interval_minutes/60)+' hours · aligned to the clock'):'Paused')+'</small>',badge(status.label,status.tone)+(x.last_error?'<small class="sources-status-warning">'+esc(x.last_error)+'</small>':''),esc(whenTime(x.last_success_at)),x.enabled?esc(whenTime(x.next_run_at)):'Paused'];}),'No refresh status is available. Saved evidence does not establish a current successful collection.')+'<div class="panel-bottom">Partial sources are bounded evidence. Expand the relevant source for its permissions, coverage window and collection diagnostics.</div>');}
function sourceCoverageSummary(){const z=state.zscaler||{},e=state.enterprise||{},r=state.rapid7||{},d=state.identityAccess||{},access=AIGovernanceReports.build(state,{}),check=s=>s.status===200?(s.partial?'Partial read':'Read available'):s.status===403?'Read denied':s.status?'HTTP '+s.status:'Unavailable';const rows=[['Zscaler',z.checked_at?'Collected '+whenTime(z.checked_at):'No saved source check',(z.sources||[]).map(x=>esc(x.name)+': '+esc(check(x))).join('<br>')||'Coverage unknown'],['Microsoft Entra',e.checked_at?'Collected '+whenTime(e.checked_at):'No saved enterprise check',(e.sources||[]).map(x=>esc(x.name||'Enterprise applications')+': '+esc(check(x))+(x.scanned!=null?' · '+Number(x.scanned)+' apps scanned':'')).join('<br>')||'Coverage unknown'],['Rapid7 InsightIDR',r.checked_at?'Collected '+whenTime(r.checked_at):'No saved activity check',(r.sources||[]).map(x=>esc(x.name)+': '+esc(check(x))).join('<br>')||'Coverage unknown'],['Directory / license access',access.identityRead?(d.checked_at?'Collected '+whenTime(d.checked_at)+(d.retained?' · Retained':''):'No saved access collection'):'Read permission or saved evidence unavailable',access.identityRead?esc(d.status||'Unknown')+'<small>Entra and Okta evidence remain separate; account counts are not a unique-person total.</small>':'Requires AI Governance and Identity Diagnostics read permission']];return '<div class="sources-coverage-summary">'+table(['Evidence source','Saved collection','Coverage'],rows.map(x=>[esc(x[0]),esc(x[1]),x[2]]))+'</div>'+(state.partial?note('Some page reads are incomplete. Available saved evidence and actual source dates remain visible.',true):'')+[z,e,r].filter(x=>x.error).map(x=>note(esc(x.error),true)).join('')+(z.shadow_it?.retained?note('Shadow IT usage is retained from '+esc(whenTime(z.shadow_it.checked_at))+'. The latest report did not refresh this evidence.',true):'')+(access.identityRead&&d.retained?note('Directory evidence is retained from '+esc(whenTime(d.checked_at))+'. Latest attempt '+esc(whenTime(d.last_attempt?.checked_at))+'.',true):access.identityRead&&d.status==='partial'?note('Directory access coverage is partial; counts are lower bounds and missing evidence remains unknown.',true):'')+(d.error?note(esc(d.error),true):'')+(r.job?.status==='failed'?note('Latest Rapid7 collection failed: '+esc(r.job.error||r.job.phase||'No error detail recorded')+'. Earlier saved evidence remains visible.',true):'');}
function sourceClassificationDetails(){return panel('Classification options',`${categories.length} primary categories · Legal’s five standard categories retained`,table(['Dimension','How to use it'],[['Primary category',esc(categories.join(' · '))],['AI type','Standalone, embedded, both or unclassified'],['Classification tags','Add multiple tags on an application, such as document drafting, meeting summaries, developer tools, Legal or HR.'],['Source evidence','Keep source record IDs, dates, feature names and suggested categories beside the reviewed record.']]),state.admin?'<button class="button" data-add-category>Add category</button>':'');}
function sourceEnterpriseDetails(){const ent=state.enterprise||{};return panel('Entra application matching',ent.checked_at?'Last checked '+new Date(ent.checked_at).toLocaleString():'No enterprise source check yet',(ent.error?note(esc(ent.error),true):'')+(ent.sources||[]).filter(x=>x.scanned!=null).map(x=>note(`${x.scanned} apps scanned · ${x.count} candidates · ${x.partial?'Partial scan':'Read completed'} · ${ent.origin==='Microsoft Graph'?'Live Microsoft Graph read':'Cached source, oldest record '+when(x.oldest_cache)}. ${esc(x.note)}`,true)).join('')+`<div class="toolbar"><input id="enterprise-filter" aria-label="Filter enterprise candidates" placeholder="Search all checked enterprise candidates…"></div><div id="enterprise-results">${sourceRows(ent.candidates||[],'enterprise')}</div>`,state.admin?'<button class="button" data-check-enterprise>Refresh Entra applications</button>':'');}
function sourceVendorDetails(){const ref=state.references||{};return panel('Embedded AI vendor references','Six starter references from official vendor documentation; this is not a comprehensive catalog',sourceRows(ref.candidates||[],'vendor'))+'<div class="section-space"></div>'+panel('Additional discovery sources','Connection status and recommended coverage',table(['Source','Status','Adds','Limitations'],(ref.registry||[]).map(x=>[evidence(x.url)+'<small>'+esc(x.name)+'</small>',esc(x.status),esc(x.provides),esc(x.limit)])));}
function sources(){return '<div class="sources-overview">'+panel('Legal classification categories',`${categories.length} primary categories · Legal’s five standard categories retained`,'<ul class="sources-category-list">'+categories.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="sources-type-note">AI type: standalone, embedded, both or unclassified.</p>')+sourceStatusPanel()+'</div>'+note('Zscaler is primary where positively matched. Supporting Entra, Okta, Rapid7 collector, original log-provider and vendor evidence retain their attribution and dates. Legal’s recorded category is separate from a vendor classification or suggestion; source presence does not establish approval, entitlement or AI-feature use.')+sourceCoverageSummary()+reportDisclosure('sources-classification','Classification guidance & category administration','Tags, evidence meanings and the existing category action',sourceClassificationDetails())+reportDisclosure('sources-refresh','Automatic refresh settings','Existing schedules, worker details and administrator controls',refreshSchedule())+reportDisclosure('sources-directory','Directory & license access evidence','Provider/app accounts, assignments, licenses and protected exports',identityAccessPanel())+reportDisclosure('sources-rapid7','Rapid7 activity evidence & diagnostics','Original providers, bounded candidates and query/recovery outcomes',rapid7Panel())+reportDisclosure('sources-entra','Entra application matching','Checked candidates, suggested classifications and existing review actions',sourceEnterpriseDetails())+reportDisclosure('sources-vendor','Vendor references & additional discovery sources','Starter references, connection status and limitations',sourceVendorDetails())+note('Public AI directories provide leads that require vendor verification. Automated website monitoring and third-party bulk catalog ingestion are not connected.');}
function categoryForm(){open('Add governance category',note('Keep Legal’s standard categories available. Custom categories become reporting options for everyone with governance access.')+`<div class="fields">${field('Category name','name','','text',true,true)}</div>`,b=>api('/categories',{method:'POST',body:JSON.stringify(b)}),'Add category');}

function render(){if(!state.loaded)return;const usageViewState=state.view==='usage'?state.usageController?.snapshot():null;const [title,sub]=titles[state.view];$('title').textContent=title;$('subtitle').textContent=sub;$('crumb').textContent=title;$('add-app').hidden=state.view!=='inventory'&&state.view!=='discovery';document.querySelectorAll('#navigation [data-view]').forEach(b=>{if(b.dataset.view===workflowSection(state.view))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelectorAll('[data-portal-view]').forEach(a=>{if(a.dataset.portalView===workflowSection(state.view))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});metrics();$('metrics').hidden=!['inventory','discovery'].includes(state.view);if(state.purposeController){state.purposeController.destroy();state.purposeController=null;}if(state.sharedController){state.sharedController.destroy();state.sharedController=null;}if(state.maintenanceController){state.maintenanceController.destroy();state.maintenanceController=null;}if(state.usageController){state.usageController.destroy();state.usageController=null;}if(state.overviewController){state.overviewController.destroy();state.overviewController=null;}if(state.useCaseController){state.useCaseController.destroy();state.useCaseController=null;}$('workspace').innerHTML=workflowLinks()+reviewScopeNote()+(state.view==='use-cases'?'<div id="use-case-view"></div>':state.view==='purpose-intake'?'<div id="purpose-view"></div>':['dashboard','attention'].includes(state.view)?'<div id="overview-view"></div>':state.view==='usage'?'<div id="usage-view"></div>':['health','intake-enrichment'].includes(state.view)?'<div id="maintenance-view"></div>':['risk','coverage','site-review','approved-sites'].includes(state.view)?'<div id="shared-ai-view"></div>':state.view==='inventory'?inventory():state.view==='discovery'?inventory(true):state.view==='projects'?userProjects():state.view==='access'?access():state.view==='requests'?requests():state.view==='audit'?audit():state.view==='sources'?sources():reports());$('workspace').setAttribute('aria-busy','false');if(['dashboard','attention'].includes(state.view))state.overviewController=AIGovernanceOverview.mount($('overview-view'),{mode:state.view,inventory:state.apps,ownerPurposeReport:state.view==='attention'?AIGovernanceReports.build(state,AIGovernanceOwnerPurpose.deepLink(location.search).filter):null,onOwnerPurposeRefresh:load});if(state.view==='usage')state.usageController=AIGovernanceUsage.mount($('usage-view'),{apps:state.apps,viewState:usageViewState,provenanceFor:id=>{const a=state.apps.find(x=>Number(x.id)===Number(id));return a?AIGovernanceReports.provenance(a,state):null;},hours:new URLSearchParams(location.search).get('usageHours'),selectedAppId:new URLSearchParams(location.search).get('usageApp')});if(['risk','coverage','site-review','approved-sites'].includes(state.view))state.sharedController=SharedAIInventory.mount($('shared-ai-view'),{mode:state.view==='site-review'?'review':state.view==='approved-sites'?'approved':state.view,appId:state.riskAppId,scopeId:state.view==='site-review'?new URLSearchParams(location.search).get('reviewApp'):null,reviewScope:'governance',sourcePartial:!!state.partial,provenanceFor:id=>{const a=state.apps.find(x=>Number(x.id)===Number(id));return a?AIGovernanceReports.provenance(a,state):null;},labels:{review:'Application Reviews',approved:'Approved Applications',risk:'Risk Assessments',coverage:'App Coverage Gaps'}});state.riskAppId=null;if(['purpose-intake','reports'].includes(state.view)){const purposeReport=AIGovernanceOwnerPurpose.attach(AIGovernanceReports.build(state,state.view==='reports'?state.reportFilter||{}:AIGovernanceOwnerPurpose.deepLink(location.search).filter));state.purposeController=AIGovernancePurpose.mount($(state.view==='reports'?'purpose-report-view':'purpose-view'),{api,apps:purposeReport.apps,model:purposeReport.ownerPurpose,admin:state.admin,open,toast,saveBlob,summaryOnly:state.view==='reports',scope:purposeReport.filter,partial:state.partial});}if(['health','intake-enrichment','requests'].includes(state.view))state.maintenanceController=AIGovernanceMaintenance.mount($('maintenance-view'),{mode:state.view==='health'?'health':state.view==='requests'?'requests':'intake'});if(state.view==='use-cases'){if(window.AIGovernanceUseCases)state.useCaseController=AIGovernanceUseCases.mount($('use-case-view'),{toast});else $('use-case-view').innerHTML='<div class="empty">The use-case view did not load. Reload the page.</div>';}}

function identityAppRows(id){return (state.identityAccess?.apps||[]).filter(x=>Number(x.catalog_id)===Number(id));}
function directoryAccessCell(a){const d=state.identityAccess;if(d?.error)return '<small>Directory access: permission required / unavailable</small>';if(!d?.checked_at)return '<small>Directory access: not collected</small>';const rows=identityAppRows(a.id);if(!rows.length)return '<small>Directory access: no verified app mapping</small>';return '<div class="section-space"><small><strong>Directory / license accounts</strong></small>'+rows.map(x=>'<small>'+esc(x.provider)+': '+Number(x.user_count)+(x.license_assigned_users?' · '+Number(x.license_assigned_users)+' licensed':'')+'</small>').join('')+'<small>'+esc(d.retained?'Retained evidence':d.status==='partial'?'Partial sample':'Collected')+' '+esc(whenTime(d.checked_at))+'</small><button type="button" class="app-link" data-identity-app="'+Number(a.id)+'">Review access evidence</button></div>';}
function identityAccessPanel(model){const r=model||AIGovernanceReports.build(state,{}),d=state.identityAccess||{};if(!r.identityRead)return panel('Directory & license access evidence','Requires AI Governance and Identity Diagnostics read permission',note(esc(d.error||'No saved access snapshot yet. Access evidence refreshes with Entra at the top of each hour.'),true));const body=note('Counts are distinct accounts per application and provider across active app instances. Direct assignments, group members and licenses overlap; do not add these columns or sum Entra and Okta as unique people. Disabled accounts can retain assignments. Grant dates and AI-feature entitlement remain separate.')+(d.retained?note('Latest attempt was incomplete. Retaining evidence collected '+esc(whenTime(d.checked_at))+'. Latest attempt '+esc(whenTime(d.last_attempt?.checked_at))+'.',true):d.status==='partial'?note('Initial access read is partial; counts are lower bounds and missing evidence remains unknown.',true):'')+table(['Application / primary label','Provider','Distinct accounts','Assignment / membership / license evidence','App instances','Details'],r.identityRows.map(x=>[appButton(x.app)+'<small>'+esc(x.app.provenance.primary_source)+' / '+esc(x.app.provenance.preferred_label)+'</small>',esc(x.provider),String(x.user_count)+'<small>'+x.disabled_user_accounts+' known disabled · '+x.account_status_unknown+' account status unknown</small>',(x.provider==='Entra'?'Direct '+x.direct_assignment_users+' · group members '+x.group_membership_users+' · licenses '+x.license_assigned_users:'Okta app assignments '+x.okta_assignment_users)+'<small>Overlapping evidence; not additive</small>',x.active_instances+' active · '+x.inactive_instances+' inactive<small>'+x.inactive_only_users+' inactive-only accounts excluded</small>','<button type="button" class="app-link" data-identity-app="'+Number(x.catalog_id)+'">Review users & evidence</button>']),'No exact app matches in this report scope')+'<div class="panel-bottom">Collected '+esc(whenTime(d.checked_at))+' · '+esc(d.status)+' · Run '+esc(d.run_id)+'. Other providers and activity evidence remain attributed to their original sources.</div>';return panel('Directory & license access evidence','Refreshed with the hourly Entra collection · provider identities kept separate',body,'<div><button class="button" data-export="identity_access">Download access summary CSV</button> <button class="button" data-identity-export-all>Download user access CSV</button></div>')+'<div class="section-space"></div>';}
async function identityUsers(id){try{const app=state.apps.find(x=>Number(x.id)===Number(id));if(!app)return;const d=await api('/identity-access/'+Number(id)+'/users');if(d.run_id!==state.identityAccess?.run_id){toast('Access evidence changed during this read. Refresh the page before reviewing or exporting.');return;}state.identityUserDetail={...d,app};open(app.app_name+' · Directory access evidence',note('One row per application/provider/account. Entra and Okta rows may represent the same person; no cross-provider identity match is assumed. Inactive-only assignments are excluded from summary counts. Dates below retain their source meaning and do not establish original access grants.')+table(['User / account','Provider','Evidence state','Source evidence and dates'],d.rows.map(u=>[esc(u.display_name||u.user_identity||'Identity not resolved')+'<small>'+esc(u.user_identity||u.provider_user_id)+'</small>',esc(u.provider),(u.evidence.some(x=>x.instance_active)?'Represented in summary':'Inactive app evidence only')+'<small>User account '+(u.account_enabled===true?'enabled':u.account_enabled===false?'disabled':'status unknown')+'</small>',u.evidence.map(x=>'<small>'+esc(human(x.kind))+' · '+esc(x.instance_name||x.sku||'')+' · '+esc(x.role||'')+' · '+esc(x.scope||x.state||'')+'<br>'+esc(x.date_meaning)+' '+esc(x.assignment_date?whenTime(x.assignment_date):'Date unknown')+'</small>').join('')]),'No returned users; this is not proof that nobody has access.')+'<p>Collected '+esc(whenTime(d.checked_at))+' · Run '+esc(d.run_id)+'</p><button type="button" class="button" data-identity-export-users>Download these user access records</button>',null);}catch(e){toast(e.message);}}
function saveIdentityUserCSV(d,apps,name){const rows=[['application','preferred_source','preferred_label','other_collected_sources','access_evidence_provider','provider_user_id','user_account','display_name','account_enabled','included_in_summary','evidence_types','source_instances','source_dates','date_meanings','roles_or_license','source_evidence_json','checked_at','collection_run_id','original_grant_date','limitation'],...d.rows.filter(u=>apps.some(a=>Number(a.id)===Number(u.catalog_id))).map(u=>{const a=apps.find(a=>Number(a.id)===Number(u.catalog_id)),p=AIGovernanceReports.provenance(a,state);return [a.app_name,p.primary_source,p.preferred_label,p.other_sources,u.provider,u.provider_user_id,u.user_identity,u.display_name,u.account_enabled,u.evidence.some(x=>x.instance_active),[...new Set(u.evidence.map(x=>x.kind))].join('; '),[...new Set(u.evidence.map(x=>x.instance_id||x.sku_id))].join('; '),u.evidence.map(x=>x.assignment_date||'Unknown').join('; '),[...new Set(u.evidence.map(x=>x.date_meaning))].join('; '),[...new Set(u.evidence.map(x=>x.role))].join('; '),JSON.stringify(u.evidence),d.checked_at,d.run_id,'Unknown','Distinct per app/provider; evidence types overlap. No verified cross-provider identity matching or original vendor grant date.'];})];saveBlob('\ufeff'+rows.map(row=>row.map(AIGovernanceReports.cell).join(',')).join('\r\n'),'text/csv;charset=utf-8',name+'-'+new Date().toLocaleDateString('en-CA')+'.csv');}
function downloadIdentityUsers(){const d=state.identityUserDetail;if(!d||d.run_id!==state.identityAccess?.run_id)return toast('Refresh access evidence before exporting.');saveIdentityUserCSV(d,[d.app],'ai-governance-access-users-'+Number(d.app.id));}
async function exportAllIdentityUsers(){try{if(state.partial)throw new Error('Refresh incomplete sources before exporting.');const d=await api('/identity-access/users');if(!d.run_id||d.run_id!==state.identityAccess?.run_id)throw new Error('Access evidence changed during this read. Refresh before exporting.');const r=AIGovernanceReports.build(state,state.view==='reports'?state.reportFilter||{}:{});saveIdentityUserCSV(d,r.apps,'ai-governance-access-users');}catch(e){toast(e.message);}}

async function load(){if(state.busy)return;state.busy=true;$('refresh').disabled=true;$('status').textContent='Refreshing governance records…';$('status').className='status-line';try{const inv=await api('/inventory');categories=inv.categories||categories;state.read_at=inv.received_at;state.apps=inv.apps.map(a=>({...a,tags:Array.isArray(a.tags)?a.tags:[],ai_type:a.ai_type||'unclassified',approval_status:a.approval_status||'unreviewed',enablement:a.enablement||'unknown'}));const jobs=await Promise.allSettled(['/requests','/access','/audit','/projects','/project-access','/project-audit'].map(p=>api(p)));const errors=[];jobs.forEach((r,i)=>{if(i===5){state.projectAudit=r.status==='fulfilled'?r.value.rows:[];state.projectRecords=r.status==='fulfilled'?r.value.grants||[]:[];state.projectGrantLimit=projectSnapshotLimit(r.status==='fulfilled'?r.value.grant_limit:null,2000);state.projectAuditLimit=projectSnapshotLimit(r.status==='fulfilled'?r.value.limit:null,500);state.projectAuditError=r.status==='rejected'?r.reason.message:'';return;}if(r.status==='fulfilled'){const d=r.value;if(i===0)state.requests=d.rows;if(i===1)state.manual=d.rows;if(i===2)state.audit=d.rows;if(i===3){state.projects=d.projects;state.links=d.links;state.projectRead=true;state.projectError='';}if(i===4)state.grants=d.rows;}else if(i>=3){state.projectRead=false;state.projects=[];state.links=[];state.grants=[];state.projectError=r.reason.message;}else{if(i===0)state.requests=[];if(i===1)state.manual=[];if(i===2)state.audit=[];errors.push(['/requests','/access','/audit'][i]+' unavailable');}});const extra=await Promise.allSettled(['/reference-sources','/enterprise-evidence','/source-evidence','/rapid7-evidence','/rapid7-observations','/risk-inventory','/identity-access'].map(p=>api(p)));state.identityAccess=extra[6].status==='fulfilled'?extra[6].value:{error:extra[6].reason.message};state.assessments=extra[5].status==='fulfilled'?{ok:true,data:extra[5].value}:{ok:false,error:extra[5].reason.message};state.rapid7=extra[3].status==='fulfilled'?extra[3].value:{error:extra[3].reason.message};if(extra[3].status==='fulfilled'&&extra[4].status==='fulfilled'&&(extra[3].value.run_id??null)!==(extra[4].value.run_id??null))errors.push('Rapid7 evidence changed during this read. Refresh before exporting');state.rapid7Observations=extra[4].status==='fulfilled'?extra[4].value.rows:[];state.rapid7ObservationRead=extra[4].status==='fulfilled';state.rapid7ObservationError=extra[4].status==='rejected'?extra[4].reason.message:'';state.references=extra[0].status==='fulfilled'?extra[0].value:{error:extra[0].reason.message};state.enterprise=extra[1].status==='fulfilled'?extra[1].value:{error:extra[1].reason.message};state.evidence=extra[2].status==='fulfilled'?extra[2].value.rows:[];if(extra[2].status==='rejected')errors.push('Additional source evidence unavailable');state.refreshStatus=await api('/refresh-status').catch(e=>({error:e.message}));state.useCases=await api('/use-cases').then(d=>({rows:d.rows||[],error:''})).catch(e=>({rows:[],error:e.message}));state.zscaler=await api('/zscaler-evidence').catch(e=>({sources:[],candidates:[],error:e.message}));state.loaded=true;$('status').textContent=errors.length?'Partial read: '+errors.join(', ')+'. Refresh before exporting.':`${state.admin?'Administrator':'Read access'} · Catalog entries are candidates until reviewed · Decisions never provision access`;$('status').className='status-line'+(errors.length?' error':'');state.partial=errors.length>0;$('updated').textContent='Inventory read '+new Date(inv.received_at).toLocaleString();render();}catch(e){$('status').textContent=e.message;$('status').className='status-line error';if(!state.loaded)$('workspace').innerHTML=empty('Governance records unavailable',e.status===403?'AI Governance access has not been granted to your account.':e.message);else{state.partial=true;$('status').textContent+=' Previously loaded records remain visible.';}}finally{state.busy=false;$('refresh').disabled=false;}}
function field(label,name,v='',type='text',full=false,required=false,help=''){return `<label class="${full?'full':''}">${esc(label)}${required?' *':''}<input name="${name}" type="${type}" value="${esc(v||'')}" ${required?'required':''} maxlength="${name.endsWith('evidence_url')?2000:name==='tags'?1000:255}">${help?`<small>${esc(help)}</small>`:''}</label>`;}
function textarea(label,name,v='',required=false){return `<label class="full">${esc(label)}${required?' *':''}<textarea name="${name}" maxlength="6000" ${required?'required':''}>${esc(v||'')}</textarea></label>`;}
function select(label,name,options,value='',required=false){return `<label>${esc(label)}${required?' *':''}<select aria-label="${esc(label)}" name="${name}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function appSelect(n){return select('Application','catalog_id',[['','Select an application'],...state.apps.map(a=>[a.id,a.app_name])],n,true);}
function open(title,body,save,button='Save record'){state.save=save;$('editor').querySelector('.dialog-footer [data-close]').textContent='Cancel';$('dialog-title').textContent=title;$('dialog-content').innerHTML=body;$('form-error').hidden=true;$('save').textContent=button;$('save').hidden=!save;$('dialog-content').scrollTop=0;if(!$('editor').open)$('editor').showModal();else $('editor').querySelector('[data-close]').focus();}
function appForm(n){const a=n?state.apps.find(a=>a.id===Number(n)):{};if(!a)return;state.editing=a.id||null;const read=!state.admin;const links=state.links.filter(l=>l.catalog_id===a.id);const fields=(n?'':field('Application name','app_name','','text',true,true))+field('Vendor','vendor',a.vendor)+field('Business owner','owner',a.owner)+select('Category','category',[['','Not classified'],...categories.map(x=>[x,x])],a.category)+select('AI type','ai_type',['unclassified','standalone','embedded','both'].map(x=>[x,human(x)]),a.ai_type||'unclassified')+select('Governance approval','approval_status',['unreviewed','under_review','approved','restricted','rejected'].map(x=>[x,human(x)]),a.approval_status||'unreviewed')+textarea('Business purpose / approved use cases','business_purpose',a.business_purpose)+field('Evidence / decision URL','evidence_url',a.evidence_url,'url',true,false,'Link to the source, ticket, vendor statement or approval. Decisions require an owner and evidence.')+field('Next review date','review_due',a.review_due?String(a.review_due).slice(0,10):'','date')+inventoryDisclosure('Additional classification details',`<div class="fields">${field('Classification tags (comma separated)','tags',(a.tags||[]).join(', '),'text',true,false,'Use additional labels for use case, business function or reporting groups.')+field('AI capability / feature','capability_name',a.capability_name,'text',true)+select('Tenant feature enablement','enablement',['unknown','available','enabled','disabled'].map(x=>[x,human(x)]),a.enablement||'unknown')}</div>`);const connected=n?`<div class="section-space"><h3>Connected projects</h3>${links.length?links.map(l=>`<p><a href="${projectUrl(l.project_id)}">${esc(l.project_name)} ↗</a> · ${esc(l.access_level)}<small class="muted"> · ${esc(l.ad_group_name)}</small>${state.admin?` <button type="button" class="app-link" data-unlink="${l.id}">Remove mapping</button>`:''}</p>`).join(''):'<p class="muted">No explicit project mappings recorded.</p>'}${state.admin&&state.projectRead?`<button type="button" class="button" data-link-app="${a.id}">Link a project</button>`:''} <a class="button" href="/zscaler-command-center.html?v=genai">AI usage & security ↗</a></div>`:'';open(n?a.app_name:'Add AI application',(n?appGlance(a):'')+(a.id?note('Primary source: '+esc(AIGovernanceReports.provenance(a,state).primary_source)+' / '+esc(AIGovernanceReports.provenance(a,state).preferred_label)+'. Supporting evidence is available below. Approval does not change policy or access.'):note('Record standalone tools and embedded AI capabilities. Approval does not change policy or access.'))+`<fieldset class="fields" style="border:0;padding:0;margin:0" ${read?'disabled':''}>${fields}</fieldset>`+(n?riskSection(a):'')+inventoryDisclosure('Connected projects',connected)+inventoryDisclosure('Usage and directory evidence',(a.id?note('<a href="'+usageUrl(a.id)+'">View automatically populated usage & observed users ↗</a>'):'')+shadowUsageForApp(a)+directoryAccessCell(a))+inventoryDisclosure('Collected source evidence',sourceEvidence(a)),read?null:async b=>{if(n)await api('/applications/'+a.id,{method:'PUT',body:JSON.stringify({...b,version:a.version||0})});else await api('/applications',{method:'POST',body:JSON.stringify(b)});},n?'Save governance record':'Add application');}
function accessForm(request=false,n=''){open(request?'Request AI access':'Record existing access',note(request?'Submitting a request starts a governance review. It does not grant access.':'Use an authoritative source for this access record. Leave the grant date blank when it is unknown.')+`<div class="fields">${appSelect(n)}${field('User email / account','user_identity','','text',false,true)}${field('Access level / role','access_level','','text',false,true)}${field('Subscription / arrangement','subscription_type','','text',false,false,'For example: enterprise license, trial or personal subscription.')}${field('AI capability / feature','capability_name','','text',true)}${textarea('Business purpose / use case','business_purpose','',request)}${request?'':field('Date access was granted','granted_at','','date',false,false,'Unknown dates stay blank; this is not the first-observed date.')}${field('Source / request URL','evidence_url','','url',true,!request)}</div>`,async b=>{await api(request?'/requests':'/access',{method:'POST',body:JSON.stringify(b)});},request?'Submit request':'Record access');}
function linkForm(n='',projectId=''){if(!state.projectRead)return;const options=state.projects.filter(p=>p.ad_group_name);open('Link application to project',note('Map a specific project group to the application or AI feature it enables. This links existing grant records and changes no memberships.')+`<div class="fields">${appSelect(n)}${select('Project and existing group','mapping',[['','Select a project group'],...options.map((p,i)=>[i,p.name+' · '+p.ad_group_name])],projectId?options.findIndex(p=>p.id===Number(projectId)):'',true)}${field('Access level enabled by this group','access_level','','text',false,true)}${field('Subscription / arrangement','subscription_type')}${field('AI capability / feature','capability_name','','text',true)}${textarea('Business purpose / scope of mapping','business_purpose','',true)}${field('Mapping evidence URL','evidence_url','','url',true,true)}</div>`,async b=>{const p=b.mapping===''?null:options[Number(b.mapping)];if(!p)throw new Error('Select a project group');await api('/project-links',{method:'POST',body:JSON.stringify({...b,project_id:p.id,ad_group_name:p.ad_group_name})});});}
function requestForm(n){const r=state.requests.find(r=>r.id===Number(n));if(!r)return;const next={submitted:['in_review','withdrawn'],in_review:['approved','rejected','withdrawn'],approved:['fulfilled','withdrawn']}[r.status]||[];const facts=`<dl class="detail-summary">${[['Application',r.app_name],['User',r.user_identity],['Requested access',r.access_level],['Status',human(r.status)],['Submitted by',r.requested_by],['Last reviewer',r.reviewed_by||'Not reviewed']].map(([k,v])=>`<div class="fact"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><h3>Business purpose</h3><p>${esc(r.business_purpose)}</p>${r.decision_note?`<h3>Latest decision note</h3><p>${esc(r.decision_note)}</p>`:''}<p>${evidence(r.evidence_url)}</p>`;open('Access request #'+r.id,note('Record the decision and its rationale. Fulfillment must reference evidence from the access-owning system.')+facts+(state.admin&&next.length?`<div class="fields">${select('Next state','status',next.map(x=>[x,human(x)]),next[0],true)}${textarea('Decision note / conditions','decision_note','',true)}${field('Fulfillment evidence URL','evidence_url','','url',true,false,'Required when marking fulfilled. A decision alone does not provision access.')}</div>`:''),state.admin&&next.length?async b=>api('/requests/'+r.id,{method:'PATCH',body:JSON.stringify({...b,version:r.version})}):null,'Record decision');}
function csvCell(v){let s=String(v==null?'':v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
$('navigation').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;state.view=b.dataset.view;location.hash=state.view;document.body.classList.remove('nav-open');$('mobile-menu').setAttribute('aria-expanded','false');render();});
$('mobile-menu').onclick=()=>{const x=document.body.classList.toggle('nav-open');$('mobile-menu').setAttribute('aria-expanded',String(x));};
$('refresh').onclick=load;$('add-app').onclick=()=>appForm();
$('workspace').addEventListener('input',e=>{if(e.target.id==='project-query'){state.projectQuery=e.target.value;$('project-results').innerHTML=projectRegisterRows();return;}if(e.target.id==='audit-query'){state.auditQuery=e.target.value;$('audit-results').innerHTML=auditResults();return;}if(e.target.id==='shadow-it-filter'){state.shadowq=e.target.value;$('shadow-it-results').innerHTML=shadowUsageRows(shadowUsageItems());return;}if(e.target.id==='rapid7-filter'){state.rapid7q=e.target.value;const q=e.target.value.toLowerCase();$('rapid7-results').innerHTML=rapid7Rows((state.rapid7.candidates||[]).filter(x=>[x.name,...(x.origins||[]),...(x.domains||[])].join(' ').toLowerCase().includes(q)));}else if(e.target.id==='rapid7-account-filter'){const q=e.target.value.toLowerCase();$('rapid7-observation-results').innerHTML=rapid7ObservationRows((state.rapid7Observations||[]).filter(x=>[x.app_name,x.user_identity,x.original_source,x.logset_name,x.log_name].join(' ').toLowerCase().includes(q)));}else if(e.target.id==='enterprise-filter'){const q=e.target.value.toLowerCase();$('enterprise-results').innerHTML=sourceRows((state.enterprise.candidates||[]).filter(x=>[x.name,x.vendor,x.capability_name,x.match_basis].join(' ').toLowerCase().includes(q)),'enterprise');}else if(e.target.id==='zscaler-filter'){const q=e.target.value.toLowerCase();$('zscaler-results').innerHTML=zscalerRows((state.zscaler.candidates||[]).filter(a=>(a.name+' '+a.code).toLowerCase().includes(q)));}else if(e.target.id==='filter-q'){state.q=e.target.value;let a=filtered();if(state.view==='discovery')a=a.filter(discoveryCandidate);const countLabel=$('workspace').querySelector(state.view==='discovery'?'.discovery-candidates .panel-header p':'.panel-header p');if(countLabel)countLabel.textContent=a.length+' matching records · standalone and embedded AI';$('app-results').innerHTML=inventoryResults(a);if($('inventory-scope'))$('inventory-scope').textContent=inventoryScope();}});
$('workspace').addEventListener('toggle',e=>{const section=e.target;if(section.matches?.('[data-report-details]')&&section.isConnected){state.reportDetails=state.reportDetails||{};state.reportDetails[section.dataset.reportDetails]=section.open;}},true);
$('workspace').addEventListener('toggle',e=>{const d=e.target;if(!d.isConnected)return;if(d.matches?.('[data-inventory-filters]'))state.inventoryFiltersOpen=d.open;else if(d.matches?.('[data-inventory-details]')){state.inventoryDetails=state.inventoryDetails||{};state.inventoryDetails[d.dataset.inventoryDetails]=d.open;}},true);
$('workspace').addEventListener('toggle',e=>{const d=e.target;if(!d.isConnected||!d.matches?.('[data-access-details]'))return;state.accessDetails=state.accessDetails||{};state.accessDetails[d.dataset.accessDetails]=d.open;},true);
$('workspace').addEventListener('change',e=>{if(e.target.id==='audit-source'){state.auditSource=e.target.value;$('audit-results').innerHTML=auditResults();return;}if(e.target.id==='shadow-it-scope'){state.shadowScope=e.target.value;$('shadow-it-results').innerHTML=shadowUsageRows(shadowUsageItems());return;}if(e.target.name&&e.target.name.startsWith('report-')){state.reportFilter=state.reportFilter||{};state.reportFilter[e.target.name.slice(7)]=e.target.value;if(state.reportFilter.from&&state.reportFilter.to&&state.reportFilter.from>state.reportFilter.to){toast('Start date must be on or before end date.');state.reportFilter[e.target.name.slice(7)]='';}render();return;}if(e.target.id==='filter-type')state.type=e.target.value;else if(e.target.id==='filter-approval')state.approval=e.target.value;else if(e.target.id==='filter-account')state.account=e.target.value;else if(e.target.id==='filter-sso')state.sso=e.target.value;else if(e.target.id==='filter-risk')state.risk=e.target.value;else if(e.target.id==='filter-source')state.source=e.target.value;else return;render();});
// Inventory: sortable headings, summary tiles as filters, and whole-row open.
$('workspace').addEventListener('click',e=>{let b;if((b=e.target.closest('[data-sort]'))){const k=b.dataset.sort;state.sort=state.sort.key===k?{key:k,dir:-state.sort.dir}:{key:k,dir:1};$('app-results').innerHTML=inventoryResults(filtered());$('app-results').querySelector('[data-sort="'+k+'"]')?.focus();return;}if((b=e.target.closest('[data-approval-pick]'))){state.approval=state.approval===b.dataset.approvalPick?'':b.dataset.approvalPick;render();return;}if((b=e.target.closest('[data-risk-pick]'))){state.risk=state.risk===b.dataset.riskPick?'':b.dataset.riskPick;render();return;}if(e.target.closest('a,button,input,select,textarea,label,summary,details')||String(getSelection?.()||''))return;const row=e.target.closest('tr[data-row-app]');if(!row)return;const u=new URL(location);u.searchParams.set('app',row.dataset.rowApp);history.replaceState(null,'',u);appForm(row.dataset.rowApp);});
async function actions(e){if(e.target.closest('[data-identity-export-all]')){await exportAllIdentityUsers();return;}let accessButton=e.target.closest('[data-identity-app]');if(accessButton){await identityUsers(accessButton.dataset.identityApp);return;}if(e.target.closest('[data-identity-export-users]')){downloadIdentityUsers();return;}let b;
if((b=e.target.closest('[data-project-view-tab]'))){projectViewTab(b.dataset.projectViewTab);return;}
if((b=e.target.closest('[data-project-filter]'))){state.projectStatus=b.dataset.projectFilter;document.querySelectorAll('[data-project-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('project-results').innerHTML=projectRegisterRows();return;}
if((b=e.target.closest('[data-project-detail-tab]'))){projectDetailTab(b.dataset.projectDetailTab);return;}
if((b=e.target.closest('[data-project-page]'))){state.projectActivityPage=Number(b.dataset.projectPage);$('project-view-panel').innerHTML=projectActivity(projectScope());$('project-view-panel').focus();return;}
if((b=e.target.closest('[data-project-history-page]'))){state.projectHistoryPage=Number(b.dataset.projectHistoryPage);projectDetailTab('history');$('project-detail-panel').focus();return;}
if((b=e.target.closest('[data-project-back]'))){const page=state.projectHistoryPage||0;projectRecord(b.dataset.projectBack);state.projectHistoryPage=page;projectDetailTab('history');return;}
if((b=e.target.closest('[data-report-assessment]'))){state.assessmentFocus=b.dataset.reportAssessment;render();$('workspace').querySelector('[data-assessment-breakdown]')?.scrollIntoView?.({block:'start'});return;}if(e.target.closest('[data-clear-assessment]')){state.assessmentFocus=null;render();return;}if((b=e.target.closest('[data-project-record]')))return projectRecord(b.dataset.projectRecord);if((b=e.target.closest('[data-project-audit]'))){const a=(state.projectAudit||[]).find(a=>a.id===Number(b.dataset.projectAudit));if(!a)return;open('Project audit event #'+a.id,`<p>${esc(projectLabel(a))} · ${esc(a.actor)} · ${esc(human(a.action))} · ${new Date(a.created_at).toLocaleString()}</p><p>Grant reference: ${esc(a.grant_id||'Project-level event')}</p><pre>${esc(JSON.stringify(typeof a.details==='string'?JSON.parse(a.details):a.details,null,2))}</pre>${b.dataset.projectParent?`<button type="button" class="button" data-project-back="${Number(b.dataset.projectParent)}">Back to project history</button>`:''}`,null);return;}if((b=e.target.closest('[data-app-risk]'))){$('editor').close();state.riskAppId=b.dataset.appRisk;state.view='risk';location.hash='risk';render();return;}if(e.target.closest('[data-export-shadow-it]'))return downloadShadowUsage();if((b=e.target.closest('[data-configure-refresh]')))return refreshScheduleForm(b.dataset.configureRefresh);if((b=e.target.closest('[data-check-rapid7]')))return checkRapid7(b);if((b=e.target.closest('[data-account]')))return accountForm(b.dataset.account);if(e.target.closest('[data-legal-brief]'))return legalBrief();if(e.target.closest('[data-add-category]'))return categoryForm();if((b=e.target.closest('[data-check-enterprise]'))){b.disabled=true;try{await api('/enterprise-refresh',{method:'POST',body:'{}',timeoutMs:240000});await load();toast('Enterprise app and access evidence refreshed.');}catch(err){toast(err.message);b.disabled=false;}return;}if((b=e.target.closest('[data-attach-source]'))){b.disabled=true;try{const r=await api('/'+b.dataset.attachSource+'-import',{method:'POST',body:JSON.stringify({code:b.dataset.sourceCode})});await load();appForm(r.id);toast('Source evidence attached; review classification and tenant enablement.');}catch(err){toast(err.message);b.disabled=false;}return;}if((b=e.target.closest('[data-check-zscaler]'))){b.disabled=true;b.textContent='Checking sources…';try{await api('/zscaler-refresh',{method:'POST',body:'{}',timeoutMs:90000});await load();toast('Zscaler source evidence refreshed.');}catch(err){toast(err.message);b.disabled=false;b.textContent='Check Zscaler sources';}}else if((b=e.target.closest('[data-import-zscaler]'))){b.disabled=true;try{const r=await api('/zscaler-import',{method:'POST',body:JSON.stringify({code:b.dataset.importZscaler})});await load();appForm(r.id);toast('Candidate imported for governance review.');}catch(err){toast(err.message);b.disabled=false;}}else if((b=e.target.closest('[data-app]'))){const u=new URL(location);u.searchParams.set('app',b.dataset.app);history.replaceState(null,'',u);appForm(b.dataset.app);}else if((b=e.target.closest('[data-link-project]')))linkForm('',b.dataset.linkProject);else if((b=e.target.closest('[data-request]')))requestForm(b.dataset.request);else if((b=e.target.closest('[data-link-app]')))linkForm(b.dataset.linkApp);else if((b=e.target.closest('[data-export]')))download(b.dataset.export);else if((b=e.target.closest('[data-action]'))){if(b.dataset.action==='link')linkForm();else accessForm(b.dataset.action==='request');}else if((b=e.target.closest('[data-audit]'))){const a=state.audit.find(a=>a.id===Number(b.dataset.audit));open('Audit event #'+a.id,`<p>${esc(a.actor)} · ${esc(human(a.action))} · ${when(a.created_at)}</p><h3>Before</h3><pre>${esc(JSON.stringify(typeof a.before_json==='string'?JSON.parse(a.before_json):a.before_json,null,2))}</pre><h3>After</h3><pre>${esc(JSON.stringify(typeof a.after_json==='string'?JSON.parse(a.after_json):a.after_json,null,2))}</pre>`,null);}else if((b=e.target.closest('[data-unlink]'))){open('Remove project mapping',note('This removes the application-to-project mapping. Project memberships and grants remain unchanged.'),async()=>api('/project-links/'+Number(b.dataset.unlink),{method:'DELETE'}),'Remove mapping');}else if((b=e.target.closest('[data-close-access]'))){open('Close access record',note('Closing marks this inventory record as closed. Revoke actual access through the owning system.')+`<p>Close recorded access #${Number(b.dataset.closeAccess)}?</p>`,async()=>api('/access/'+Number(b.dataset.closeAccess),{method:'PATCH',body:'{}'}),'Close record');}}
$('workspace').addEventListener('keydown',projectTabKeys);$('dialog-content').addEventListener('keydown',projectTabKeys);
$('workspace').addEventListener('click',actions);$('dialog-content').addEventListener('click',actions);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('editor').close());
$('editor-form').addEventListener('submit',async e=>{e.preventDefault();if(!state.save)return;const b=Object.fromEntries(new FormData(e.target));$('save').disabled=true;$('form-error').hidden=true;try{await state.save(b);$('editor').close();toast('Governance record saved.');await load();}catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false;}finally{$('save').disabled=false;}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v]&&state.view!==v){state.view=v;render();}});
async function init(){try{await itRbac.ready();state.admin=itRbac.isVerified()&&itRbac.canAccess('ai-governance');$('add-app').disabled=!state.admin;state.view=titles[location.hash.slice(1)]?location.hash.slice(1):'dashboard';if(state.view==='risk')state.riskAppId=new URLSearchParams(location.search).get('riskApp');await load();const a=new URLSearchParams(location.search).get('app');if(state.loaded&&a)appForm(a);const account=new URLSearchParams(location.search).get('accountApp');if(state.loaded&&account)accountForm(account);}catch(e){$('status').textContent='Access could not be verified. Reload to try again.';$('status').className='status-line error';}}
init();
setInterval(()=>{if(document.visibilityState==='visible'&&!state.busy&&!$('editor').open&&!state.useCaseController?.busy()&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!Array.from(document.querySelectorAll('#workspace input')).some(e=>e.value&&e.type!=='date'))load();},300000);
})();
